        }
      } else {
        lineDensityProg = ldt.to;
      }
      lineDensityProgRef.value = lineDensityProg;

      // --- Window transition ---
      const transition = windowTransitionRef.value;
      const windowResult = updateCandleWindowTransition(cfg.windowSecs, transition, displayWindowRef.value, displayMinRef.value, displayMaxRef.value, now_ms, now, effectiveCandles, rawLive, candleWidthSecs, candleBuffer);
      displayWindowRef.value = windowResult.windowSecs;
      const windowSecs = windowResult.windowSecs;
      const windowTransProgress = windowResult.windowTransProgress;
      const isWindowTransitioning = transition.startMs > 0;
      const rightEdge = now + windowSecs * candleBuffer;
      const leftEdge = rightEdge - windowSecs;

      // --- Live candle OHLC lerp ---
      let smoothLive: CandlePoint | undefined;
      if (rawLive) {
        const prev = displayCandleRef.value;
        if (!prev || prev.time !== rawLive.time) {
          displayCandleRef.value = {
            time: rawLive.time,
            open: rawLive.open,
            high: rawLive.open,
            low: rawLive.open,
            close: rawLive.open
          };
          liveBirthAlphaRef.value = 0;
        } else {
          const dc = displayCandleRef.value!;
          dc.open = lerp(dc.open, rawLive.open, CANDLE_LERP_SPEED, pausedDt);
          dc.high = lerp(dc.high, rawLive.high, CANDLE_LERP_SPEED, pausedDt);
          dc.low = lerp(dc.low, rawLive.low, CANDLE_LERP_SPEED, pausedDt);
          dc.close = lerp(dc.close, rawLive.close, CANDLE_LERP_SPEED, pausedDt);
        }
        liveBirthAlphaRef.value = lerp(liveBirthAlphaRef.value, 1, 0.2, pausedDt);
        if (liveBirthAlphaRef.value > 0.99) liveBirthAlphaRef.value = 1;
        const dc = displayCandleRef.value!;
        const bullTarget = dc.close >= dc.open ? 1 : 0;
        liveBullRef.value = lerp(liveBullRef.value, bullTarget, 0.12, pausedDt);
        if (liveBullRef.value > 0.99) liveBullRef.value = 1;
        if (liveBullRef.value < 0.01) liveBullRef.value = 0;
        smoothLive = dc;
      } else {
        displayCandleRef.value = null;
        liveBirthAlphaRef.value = 1;
        liveBullRef.value = 0.5;
      }

      // --- Smooth close for dashed price line ---
      // Tracks rawLive.close at candle-body speed but never resets on candle
      // birth, so the dashed line doesn't jump when a new candle starts.
      if (rawLive) {
        if (!closeLineSmoothInitedRef.value) {
          closeLineSmoothRef.value = rawLive.close;
          closeLineSmoothInitedRef.value = true;
        } else {
          closeLineSmoothRef.value = lerp(closeLineSmoothRef.value, rawLive.close, CLOSE_LINE_LERP_SPEED, pausedDt);
          const gap = Math.abs(closeLineSmoothRef.value - rawLive.close);
          const range = displayMaxRef.value - displayMinRef.value || 1;
          if (gap < range * 0.0005) closeLineSmoothRef.value = rawLive.close;
        }
      } else if (!useStash) {
        closeLineSmoothInitedRef.value = false;
      }

      // --- Smooth close for line mode ---
      if (rawLive) {
        if (!lineSmoothInitedRef.value) {
          lineSmoothCloseRef.value = rawLive.close;
          lineSmoothInitedRef.value = true;
        } else {
          const valGap = Math.abs(rawLive.close - lineSmoothCloseRef.value);
          const prevRange = displayMaxRef.value - displayMinRef.value || 1;
          const gapRatio = Math.min(valGap / prevRange, 1);
          const adaptiveSpeed = LINE_LERP_BASE + (1 - gapRatio) * LINE_ADAPTIVE_BOOST;
          lineSmoothCloseRef.value = lerp(lineSmoothCloseRef.value, rawLive.close, adaptiveSpeed, pausedDt);
          if (valGap < prevRange * LINE_SNAP_THRESHOLD) lineSmoothCloseRef.value = rawLive.close;
        }
      } else if (!useStash) {
        // Only reset when not using stash — during reverse morph,
        // freeze the smooth value (matches line mode's displayValueRef freeze)
        lineSmoothInitedRef.value = false;
      }

      // --- Smooth tick value for density transition ---
      if (effectiveLineValue !== undefined && hasTickData) {
        if (!lineTickSmoothInitedRef.value) {
          lineTickSmoothRef.value = effectiveLineValue;
          lineTickSmoothInitedRef.value = true;
        } else {
          const valGap = Math.abs(effectiveLineValue - lineTickSmoothRef.value);
          const prevRange = displayMaxRef.value - displayMinRef.value || 1;
          const gapRatio = Math.min(valGap / prevRange, 1);
          const adaptiveSpeed = LINE_LERP_BASE + (1 - gapRatio) * LINE_ADAPTIVE_BOOST;
          lineTickSmoothRef.value = lerp(lineTickSmoothRef.value, effectiveLineValue, adaptiveSpeed, pausedDt);
          if (valGap < prevRange * LINE_SNAP_THRESHOLD) lineTickSmoothRef.value = effectiveLineValue;
        }
      } else if (!useStash) {
        lineTickSmoothInitedRef.value = false;
      }

      // --- Build visible candles ---
      const visible: CandlePoint[] = [];
      for (const c of effectiveCandles) {
        if (c.time + candleWidthSecs >= leftEdge && c.time <= rightEdge) visible.push(c);
      }
      if (smoothLive && smoothLive.time + displayCandleWidth >= leftEdge && smoothLive.time <= rightEdge) {
        visible.push(smoothLive);
      }
      let oldVisible: CandlePoint[] = [];
      if (morphT >= 0 && cwt.oldCandles.length > 0) {
        for (const c of cwt.oldCandles) {
          if (c.time + cwt.oldWidth >= leftEdge && c.time <= rightEdge) oldVisible.push(c);
        }
      }

      // Stash visible candles for reverse morph
      if (hasData) {
        lastCandlesRef.value = visible;
        lastLiveRef.value = smoothLive ?? null;
      }
      const effectiveVisible = useStash ? lastCandlesRef.value : visible;
      const effectiveLive = useStash ? lastLiveRef.value ?? undefined : smoothLive;

      // --- Range computation ---
      // Always use full OHLC range regardless of line mode progress.
      // The close-only and tick-level ranges are tighter (no wicks),
      // so blending between them during morphs shifts the Y axis and
      // causes visible grid label drift + line position jumps.
      // Using one consistent OHLC range means zero range change during
      // the morph — the line gets slightly more Y margin in line mode
      // (room for wicks it doesn't use) but that's an acceptable trade-off.
      const chartW = w - pad.left - pad.right;
      const computed = effectiveVisible.length > 0 ? computeCandleRange(effectiveVisible) : {
        min: displayMinRef.value,
        max: displayMaxRef.value
      };
      const rangeResult = updateCandleRange(computed, rangeInitedRef.value, displayMinRef.value, displayMaxRef.value, isWindowTransitioning, windowTransProgress, transition, chartH, pausedDt);
      if (morphT >= 0) {
        rangeResult.displayMin = cwt.rangeFromMin + (cwt.rangeToMin - cwt.rangeFromMin) * morphT;
        rangeResult.displayMax = cwt.rangeFromMax + (cwt.rangeToMax - cwt.rangeFromMax) * morphT;
        rangeResult.minVal = rangeResult.displayMin;
        rangeResult.maxVal = rangeResult.displayMax;
        rangeResult.valRange = rangeResult.displayMax - rangeResult.displayMin || 0.001;
      }
      rangeInitedRef.value = rangeResult.rangeInited;
      displayMinRef.value = rangeResult.displayMin;
      displayMaxRef.value = rangeResult.displayMax;
      const {
        minVal,
        maxVal,
        valRange
      } = rangeResult;
      const layout: ChartLayout = {
        w,
        h,
        pad,
        chartW,
        chartH,
        leftEdge,
        rightEdge,
        minVal,
        maxVal,
        valRange,
        toX: (t: number) => pad.left + (t - leftEdge) / (rightEdge - leftEdge) * chartW,
        toY: (v: number) => pad.top + (1 - (v - minVal) / valRange) * chartH
      };

      // --- Hover + scrub ---
      const hoverPx = hoverXRef.value;
      let hoveredCandle: CandlePoint | null = null;
      let isActiveHover = false;
      if (hoverPx !== null && hoverPx >= pad.left && hoverPx <= w - pad.right) {
        hoveredCandle = candleAtX(effectiveVisible, hoverPx, displayCandleWidth, layout);
        if (hoveredCandle) isActiveHover = true;
      }
      const scrubTarget = isActiveHover ? 1 : 0;
      scrubAmountRef.value = lerp(scrubAmountRef.value, scrubTarget, 0.12, dt);
      if (scrubAmountRef.value < 0.01) scrubAmountRef.value = 0;
      if (scrubAmountRef.value > 0.99) scrubAmountRef.value = 1;
      const scrubAmount = scrubAmountRef.value;
      let drawHoverX = hoverPx;
      let drawHoverTime = 0;
      let drawHoverCandle: CandlePoint | null = hoveredCandle;
      if (!isActiveHover && scrubAmount > 0 && lastHoverRef.value) {
        drawHoverX = lastHoverRef.value.x;
        drawHoverTime = lastHoverRef.value.time;
        drawHoverCandle = candleAtX(effectiveVisible, lastHoverRef.value.x, displayCandleWidth, layout);
      } else if (isActiveHover && hoverPx !== null) {
        drawHoverTime = layout.leftEdge + (hoverPx - pad.left) / chartW * (layout.rightEdge - layout.leftEdge);
        lastHoverRef.value = {
          x: hoverPx,
          value: hoveredCandle?.close ?? 0,
          time: drawHoverTime
        };
      }
      let drawCandles = effectiveVisible;
      let drawOldCandles = oldVisible;
      let drawLive = effectiveLive;

      // Line mode: blend live close toward smooth close
      if (lineModeProg > 0.01 && drawLive && lineSmoothInitedRef.value) {
        const blended = drawLive.close + (lineSmoothCloseRef.value - drawLive.close) * lineModeProg;
        drawLive = {
          ...drawLive,
          close: blended
        };
        const li = drawCandles.length - 1;
        if (li >= 0 && drawCandles[li].time === drawLive.time) {
          drawCandles = drawCandles.slice();
          drawCandles[li] = {
            ...drawCandles[li],
            close: blended
          };
        }
      }

      // Line mode OHLC collapse
      if (lineModeProg > 0.01 && lineModeProg < 0.99) {
        const collapseOHLC = (c: CandlePoint): CandlePoint => {
          const inv = 1 - lineModeProg;
          return {
            time: c.time,
            open: c.close + (c.open - c.close) * inv,
            high: c.close + (c.high - c.close) * inv,
            low: c.close + (c.low - c.close) * inv,
            close: c.close
          };
        };
        drawCandles = drawCandles.map(collapseOHLC);
        if (drawOldCandles.length > 0) drawOldCandles = drawOldCandles.map(collapseOHLC);
        if (drawLive) drawLive = collapseOHLC(drawLive);
      }

      // Build lineVisible for drawLine — value-space points that drawLine
      // converts to screen coords with its own morphY/alpha/color logic.
      // Use tick-level resolution whenever the line is visible (lineModeProg > 0.05),
      // not just when lineDensityProg > 0.01.  The density transition finishes
      // 150ms before the line fades out; without this, lineVisible abruptly drops
      // from ~300 smooth points to ~5 stepped candle-close points while the line
      // is still at ~30% opacity, causing a visible shape jump.
      let lineVisible: LivelinePoint[];
      let lineSmoothValue: number;
      if (effectiveLineData && effectiveLineData.length > 0 && (lineDensityProg > 0.01 || lineModeProg > 0.05)) {
        // Density transition: blend candle-close values toward tick values
        const closeRefs: {
          t: number;
          v: number;
        }[] = [];
        for (const c of drawCandles) {
          closeRefs.push({
            t: c.time + displayCandleWidth / 2,
            v: c.close
          });
        }
        if (drawLive) closeRefs.push({
          t: now,
          v: drawLive.close
        });
        lineVisible = [];
        let refIdx = 0;
        for (const pt of effectiveLineData) {
          if (pt.time < leftEdge || pt.time > rightEdge) continue;
          while (refIdx < closeRefs.length - 2 && closeRefs[refIdx + 1].t < pt.time) refIdx++;
          let interpClose: number;
          if (closeRefs.length === 0) {
            interpClose = pt.value;
          } else if (closeRefs.length === 1 || pt.time <= closeRefs[0].t) {
            interpClose = closeRefs[0].v;
          } else if (refIdx >= closeRefs.length - 1) {
            interpClose = closeRefs[closeRefs.length - 1].v;
          } else {
            const a = closeRefs[refIdx];
            const b = closeRefs[refIdx + 1];
            const span = b.t - a.t;
            const frac = span > 0 ? Math.max(0, Math.min(1, (pt.time - a.t) / span)) : 0;
            interpClose = a.v + (b.v - a.v) * frac;
          }
          const blended = interpClose + (pt.value - interpClose) * lineDensityProg;
          lineVisible.push({
            time: pt.time,
            value: blended
          });
        }
        const smoothTick = lineTickSmoothInitedRef.value ? lineTickSmoothRef.value : effectiveLineValue ?? effectiveLineData[effectiveLineData.length - 1].value;
        // No explicit live tip — drawLine appends one at toX(now) using lineSmoothValue
        lineSmoothValue = lineSmoothCloseRef.value + (smoothTick - lineSmoothCloseRef.value) * lineDensityProg;
      } else {
        // Candle-close resolution — no live tip; drawLine appends one at toX(now)
        lineVisible = drawCandles.map(c => ({
          time: c.time + displayCandleWidth / 2,
          value: c.close
        }));
        lineSmoothValue = lineSmoothInitedRef.value ? lineSmoothCloseRef.value : drawLive?.close ?? drawCandles[drawCandles.length - 1]?.close ?? 0;
      }

      // Pad lineVisible to span full chart width during reveal morph.
      // Without this, data that doesn't fill the window creates a partial-width
      // line that pops when it hands off to the full-width loading squiggly.
      if (chartReveal < 1 && lineVisible.length >= 2) {
        const firstTime = lineVisible[0].time;
        const windowSpan = rightEdge - leftEdge;
        if (firstTime - leftEdge > windowSpan * 0.05) {
          const firstVal = lineVisible[0].value;
          const step = windowSpan / 32;
          const padded: LivelinePoint[] = [];
          for (let t = leftEdge; t < firstTime - step * 0.5; t += step) {
            padded.push({
              time: t,
              value: firstVal
            });
          }
          lineVisible = [...padded, ...lineVisible];
        }
      }

      // --- Draw ---
      drawCandleFrame(ctx, layout, cfg.palette, {
        candles: drawCandles,
        displayCandleWidth,
        oldCandles: drawOldCandles,
        oldWidth: cwt.oldWidth,
        morphT,
        liveCandle: drawLive,
        closePriceCandle: closeLineSmoothInitedRef.value && rawLive ? {
          ...rawLive,
          close: closeLineSmoothRef.value
        } : rawLive,
        liveTime: effectiveLive?.time ?? -1,
        liveBirthAlpha: liveBirthAlphaRef.value,
        liveBullBlend: liveBullRef.value,
        lineModeProg,
        chartReveal,
        now_ms,
        now,
        pauseProgress,
        showGrid: cfg.showGrid,
        scrubAmount,
        hoverX: drawHoverX,
        hoverValue: drawHoverCandle?.close ?? null,
        hoverTime: drawHoverTime,
        hoveredCandle: drawHoverCandle,
        formatValue: cfg.formatValue,
        formatTime: cfg.formatTime,
        gridState: gridStateRef.value,
        timeAxisState: timeAxisStateRef.value,
        dt: pausedDt,
        targetWindowSecs: cfg.windowSecs,
        tooltipY: cfg.tooltipY,
        tooltipOutline: cfg.tooltipOutline,
        lineVisible,
        lineSmoothValue,
        emptyText: cfg.emptyText,
        loadingAlpha,
        // Show empty overlay when not loading AND loadingAlpha has fully
        // decayed. This prevents the gradient gap from flashing during
        // loading→live (where loadingAlpha starts at ~1), while still
        // allowing smooth fade-out during empty→live (loadingAlpha is 0).
        showEmptyOverlay: !(cfg.loading ?? false) && loadingAlpha < 0.01
      });

      // Badge in candle mode — only when in line mode (lineModeProg > 0.5)
      if (badgeRef.value) {
        if (lineModeProg > 0.5 && cfg.showBadge) {
          const momentum = detectMomentum(lineVisible);
          badgeYRef.value = updateBadgeDOM(badgeRef.value, cfg, lineSmoothValue, layout, momentum, badgeYRef.value, badgeColorRef.value, isWindowTransitioning, noMotion, ctx, pausedDt, chartReveal);
          // Fade badge in/out with lineModeProg (0.5→1 maps to 0→1)
          const badgeFade = (lineModeProg - 0.5) * 2;
          if (badgeRef.value.container.style.display !== 'none') {
            const base = badgeRef.value.container.style.opacity ? parseFloat(badgeRef.value.container.style.opacity) : 1;
            badgeRef.value.container.style.opacity = String(base * badgeFade * (1 - pauseProgress));
          }
        } else {
          badgeRef.value.container.style.display = 'none';
        }
      }
    } else if (cfg.isMultiSeries && cfg.multiSeries && cfg.multiSeries.length > 0 || useMultiStash) {
      // ═══════════════════════════════════════════════════════
      // MULTI-SERIES LINE MODE PIPELINE
      // ═══════════════════════════════════════════════════════

      const effectiveMultiSeries = useMultiStash ? lastMultiSeriesRef.value : cfg.multiSeries!;

      // Reserve just enough right-side space so endpoint labels don't overlap
      // grid value text (which starts at w - pad.right + 8). Labels are drawn
      // at lineEnd + 6, so overlap = labelW + 6 - 8 = labelW - 2.
      // Scale with chartReveal so layout doesn't shift during loading collapse.
      let labelReserve = 0;
      if (effectiveMultiSeries.some(s => s.label)) {
        ctx.font = '600 10px -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif';
        let maxLabelW = 0;
        for (const s of effectiveMultiSeries) {
          if (s.label) {
            const lw = ctx.measureText(s.label).width;
            if (lw > maxLabelW) maxLabelW = lw;
          }
        }
        labelReserve = Math.max(0, maxLabelW - 2) * chartReveal;
      }
      const chartW = w - pad.left - pad.right - labelReserve;
      const buffer = cfg.showBadge ? WINDOW_BUFFER : WINDOW_BUFFER_NO_BADGE;

      // Clean stale entries from displayValuesRef (series that were removed)
      if (!useMultiStash) {
        const currentIds = new Set(effectiveMultiSeries.map(s => s.id));
        for (const key of displayValuesRef.value.keys()) {
          if (!currentIds.has(key)) displayValuesRef.value.delete(key);
        }
      }

      // Use first series data for window transition seeding
      const firstSeries = effectiveMultiSeries[0];
      const transition = windowTransitionRef.value;
      if (hasData) frozenNowRef.value = Date.now() / 1000 - timeDebtRef.value;
      const now = useMultiStash ? frozenNowRef.value : Date.now() / 1000 - timeDebtRef.value;

      // Per-series smooth values (freeze when using stash)
      const smoothValues = new Map<string, number>();
      for (const s of effectiveMultiSeries) {
        let dv = displayValuesRef.value.get(s.id);
        if (dv === undefined) dv = s.value;
        if (!useMultiStash) {
          const adaptiveSpeed = computeAdaptiveSpeed(s.value, dv, displayMinRef.value, displayMaxRef.value, cfg.lerpSpeed, noMotion);
          dv = lerp(dv, s.value, adaptiveSpeed, pausedDt);
          const prevRange = displayMaxRef.value - displayMinRef.value || 1;
          if (Math.abs(dv - s.value) < prevRange * VALUE_SNAP_THRESHOLD) dv = s.value;
          displayValuesRef.value.set(s.id, dv);
        }
        smoothValues.set(s.id, dv);
      }

      // Per-series visibility alpha (lerp toward 0 for hidden, 1 for visible)
      const hiddenIds = cfg.hiddenSeriesIds;
      const seriesAlphas = seriesAlphaRef.value;
      for (const s of effectiveMultiSeries) {
        let alpha = seriesAlphas.get(s.id) ?? 1;
        const target = hiddenIds?.has(s.id) ? 0 : 1;
        alpha = noMotion ? target : lerp(alpha, target, SERIES_TOGGLE_SPEED, pausedDt);
        if (alpha < 0.01) alpha = 0;
        if (alpha > 0.99) alpha = 1;
        seriesAlphas.set(s.id, alpha);
      }

      // Window transition — seed with all series data for accurate range
      const firstData = pausedMultiDataRef.value?.get(firstSeries.id)?.data ?? firstSeries.data;
      const windowResult = updateWindowTransition(cfg, transition, displayWindowRef.value, displayMinRef.value, displayMaxRef.value, noMotion, now_ms, now, firstData, smoothValues.get(firstSeries.id) ?? firstSeries.value, buffer);
      // Override range target with union of ALL series (not just first)
      if (transition.startMs > 0 && effectiveMultiSeries.length > 1) {
        const targetRightEdge = now + cfg.windowSecs * buffer;
        const targetLeftEdge = targetRightEdge - cfg.windowSecs;
        let unionMin = Infinity;
        let unionMax = -Infinity;
        for (const s of effectiveMultiSeries) {
          const sData = pausedMultiDataRef.value?.get(s.id)?.data ?? s.data;
          const sv = smoothValues.get(s.id) ?? s.value;
          const targetVisible: LivelinePoint[] = [];
          for (const p of sData) {
            if (p.time >= targetLeftEdge - 2 && p.time <= targetRightEdge) targetVisible.push(p);
          }
          if (targetVisible.length > 0) {
            const range = computeRange(targetVisible, sv, cfg.referenceLine?.value, cfg.exaggerate);
            if (range.min < unionMin) unionMin = range.min;
            if (range.max > unionMax) unionMax = range.max;
          }
        }
        if (isFinite(unionMin) && isFinite(unionMax)) {
          transition.rangeToMin = unionMin;
          transition.rangeToMax = unionMax;
        }
      }
      displayWindowRef.value = windowResult.windowSecs;
      const windowSecs = windowResult.windowSecs;
      const windowTransProgress = windowResult.windowTransProgress;
      const isWindowTransitioning = transition.startMs > 0;
      const rightEdge = now + windowSecs * buffer;
      const leftEdge = rightEdge - windowSecs;
      const filterRight = rightEdge - (rightEdge - now) * pauseProgress;

      // Build per-series visible arrays and compute global range
      // Use paused snapshots when available to prevent left-edge erosion
      // Exclude hidden series (alpha < 0.01) from range so Y-axis adjusts
      const seriesEntries: MultiSeriesEntry[] = [];
      let globalMin = Infinity;
      let globalMax = -Infinity;
      for (const s of effectiveMultiSeries) {
        const snap = pausedMultiDataRef.value?.get(s.id);
        const seriesData = snap?.data ?? s.data;
        const visible: LivelinePoint[] = [];
        for (const p of seriesData) {
          if (p.time >= leftEdge - 2 && p.time <= filterRight) visible.push(p);
        }
        const sv = smoothValues.get(s.id) ?? s.value;
        const alpha = seriesAlphas.get(s.id) ?? 1;
        if (visible.length >= 2) {
          // Only include in range if series is at least partially visible
          if (alpha > 0.01) {
            const range = computeRange(visible, sv, cfg.referenceLine?.value, cfg.exaggerate);
            if (range.min < globalMin) globalMin = range.min;
            if (range.max > globalMax) globalMax = range.max;
          }
          // Always push to entries (drawMultiFrame skips via alpha)
          seriesEntries.push({
            visible,
            smoothValue: sv,
            palette: s.palette,
            label: s.label,
            alpha
          });
        }
      }
      if (seriesEntries.length === 0) {
        // No visible data — draw loading/empty fallback (matching single-series behavior)
        // Grey loading line for multi-series (no single accent color to use)
        if (loadingAlpha > 0.01) {
          drawLoading(ctx, w, h, pad, cfg.palette, now_ms, loadingAlpha, cfg.palette.gridLabel);
        }
        if (1 - loadingAlpha > 0.01) {
          drawEmpty(ctx, w, h, pad, cfg.palette, 1 - loadingAlpha, now_ms, false, cfg.emptyText);
        }
        ctx.save();
        ctx.globalCompositeOperation = 'destination-out';
        const fadeGrad = ctx.createLinearGradient(pad.left, 0, pad.left + FADE_EDGE_WIDTH, 0);
        fadeGrad.addColorStop(0, 'rgba(0, 0, 0, 1)');
        fadeGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
        ctx.fillStyle = fadeGrad;
        ctx.fillRect(0, 0, pad.left + FADE_EDGE_WIDTH, h);
        ctx.restore();
        if (badgeRef.value) badgeRef.value.container.style.display = 'none';
        rafRef.value = requestAnimationFrame(draw);
        return;
      }

      // Smooth global range
      const computedRange = {
        min: isFinite(globalMin) ? globalMin : 0,
        max: isFinite(globalMax) ? globalMax : 1
      };
      const adaptiveSpeed = cfg.lerpSpeed + ADAPTIVE_SPEED_BOOST * 0.5;
      const rangeResult = updateRange(computedRange, rangeInitedRef.value, targetMinRef.value, targetMaxRef.value, displayMinRef.value, displayMaxRef.value, isWindowTransitioning, windowTransProgress, transition, adaptiveSpeed, chartH, pausedDt);
      rangeInitedRef.value = rangeResult.rangeInited;
      targetMinRef.value = rangeResult.targetMin;
      targetMaxRef.value = rangeResult.targetMax;
      displayMinRef.value = rangeResult.displayMin;
      displayMaxRef.value = rangeResult.displayMax;
      const {
        minVal,
        maxVal,
        valRange
      } = rangeResult;
      const layout: ChartLayout = {
        w,
        h,
        pad,
        chartW,
        chartH,
        leftEdge,
        rightEdge,
        minVal,
        maxVal,
        valRange,
        toX: (t: number) => pad.left + (t - leftEdge) / (rightEdge - leftEdge) * chartW,
        toY: (v: number) => pad.top + (1 - (v - minVal) / valRange) * chartH
      };

      // Hover — interpolate value at hover time for each series
      const hoverPx = hoverXRef.value;
      let drawHoverX: number | null = null;
      let drawHoverTime: number | null = null;
      let isActiveHover = false;
      let hoverEntries: {
        color: string;
        label: string;
        value: number;
      }[] = [];
      if (hoverPx !== null && hoverPx >= pad.left && hoverPx <= w - pad.right) {
        const maxHoverX = layout.toX(now);
        const clampedX = Math.min(hoverPx, maxHoverX);
        const t = leftEdge + (clampedX - pad.left) / chartW * (rightEdge - leftEdge);
        drawHoverX = clampedX;
        drawHoverTime = t;
        isActiveHover = true;
        for (const entry of seriesEntries) {
          // Skip hidden series from crosshair tooltip
          if ((entry.alpha ?? 1) < 0.5) continue;
          const v = interpolateAtTime(entry.visible, t);
          if (v !== null) {
            hoverEntries.push({
              color: entry.palette.line,
              label: entry.label ?? '',
              value: v
            });
          }
        }
        lastHoverRef.value = {
          x: clampedX,
          value: hoverEntries[0]?.value ?? 0,
          time: t
        };
        lastHoverEntriesRef.value = hoverEntries;
        cfg.onHover?.({
          time: t,
          value: hoverEntries[0]?.value ?? 0,
          x: clampedX,
          y: layout.toY(hoverEntries[0]?.value ?? 0)
        });
      }

      // Scrub amount
      const scrubTarget = isActiveHover ? 1 : 0;
      if (noMotion) {
        scrubAmountRef.value = scrubTarget;
      } else {
        scrubAmountRef.value += (scrubTarget - scrubAmountRef.value) * SCRUB_LERP_SPEED;
        if (scrubAmountRef.value < 0.01) scrubAmountRef.value = 0;
        if (scrubAmountRef.value > 0.99) scrubAmountRef.value = 1;
      }

      // Fade-out: use last known hover position + cached entries
      if (!isActiveHover && scrubAmountRef.value > 0 && lastHoverRef.value) {
        drawHoverX = lastHoverRef.value.x;
        drawHoverTime = lastHoverRef.value.time;
        hoverEntries = lastHoverEntriesRef.value;
      }

      // Draw multi-series frame
      drawMultiFrame(ctx, layout, {
        series: seriesEntries,
        now,
        showGrid: cfg.showGrid,
        showPulse: cfg.showPulse,
        referenceLine: cfg.referenceLine,
        hoverX: drawHoverX,
        hoverTime: drawHoverTime,
        hoverEntries,
        scrubAmount: scrubAmountRef.value,
        windowSecs,
        formatValue: cfg.formatValue,
        formatTime: cfg.formatTime,
        gridState: gridStateRef.value,
        timeAxisState: timeAxisStateRef.value,
        dt,
        targetWindowSecs: cfg.windowSecs,
        tooltipY: cfg.tooltipY,
        tooltipOutline: cfg.tooltipOutline,
        chartReveal,
        pauseProgress,
        now_ms,
        primaryPalette: cfg.palette
      });

      // During reverse morph (chart → loading/empty), overlay the empty text
      // as chartReveal drops — identical to single-series behavior
      const bgAlpha = 1 - chartReveal;
      if (bgAlpha > 0.01 && revealTarget === 0 && !cfg.loading) {
        const bgEmptyAlpha = (1 - loadingAlpha) * bgAlpha;
        if (bgEmptyAlpha > 0.01) {
          drawEmpty(ctx, w, h, pad, cfg.palette, bgEmptyAlpha, now_ms, true, cfg.emptyText);
        }
      }

      // Hide badge in multi-series mode
      if (badgeRef.value) badgeRef.value.container.style.display = 'none';
    } else {
      // ═══════════════════════════════════════════════════════
      // LINE MODE PIPELINE (existing)
      // ═══════════════════════════════════════════════════════

      const effectivePoints = useStash ? lastDataRef.value : points;

      // Adaptive speed + smooth value (freeze lerp when using stashed data)
      const adaptiveSpeed = computeAdaptiveSpeed(cfg.value, displayValueRef.value, displayMinRef.value, displayMaxRef.value, cfg.lerpSpeed, noMotion);
      if (!useStash) {
        displayValueRef.value = lerp(displayValueRef.value, cfg.value, adaptiveSpeed, pausedDt);
        // Skip snap when pausing — cfg.value keeps changing from the consumer,
        // so the snap would cause visible jumps in a supposedly frozen chart
        if (pauseProgress < 0.5) {
          const prevRange = displayMaxRef.value - displayMinRef.value || 1;
          if (Math.abs(displayValueRef.value - cfg.value) < prevRange * VALUE_SNAP_THRESHOLD) {
            displayValueRef.value = cfg.value;
          }
        }
      }
      const smoothValue = displayValueRef.value;
      const chartW = w - pad.left - pad.right;

      // Dynamic buffer: when badge is off, use a smaller buffer so the dot
      // sits closer to the right edge. When momentum arrows + badge are both
      // on, ensure enough gap for the arrows to fit.
      const baseBuffer = cfg.showBadge ? WINDOW_BUFFER : WINDOW_BUFFER_NO_BADGE;
      const needsArrowRoom = cfg.showMomentum && cfg.showBadge;
      const buffer = needsArrowRoom ? Math.max(baseBuffer, 37 / Math.max(chartW, 1)) : baseBuffer;

      // Window transition
      const transition = windowTransitionRef.value;
      if (hasData) frozenNowRef.value = Date.now() / 1000 - timeDebtRef.value;
      const now = useStash ? frozenNowRef.value : Date.now() / 1000 - timeDebtRef.value;
      const windowResult = updateWindowTransition(cfg, transition, displayWindowRef.value, displayMinRef.value, displayMaxRef.value, noMotion, now_ms, now, effectivePoints, smoothValue, buffer);
      displayWindowRef.value = windowResult.windowSecs;
      const windowSecs = windowResult.windowSecs;
      const windowTransProgress = windowResult.windowTransProgress;
      const rightEdge = now + windowSecs * buffer;
      const leftEdge = rightEdge - windowSecs;

      // Filter visible points — when pausing, contract right edge to `now`
      // so new data (with real-time timestamps) can't appear past the live dot
      const filterRight = rightEdge - (rightEdge - now) * pauseProgress;
      const visible: LivelinePoint[] = [];
      for (const p of effectivePoints) {
        if (p.time >= leftEdge - 2 && p.time <= filterRight) {
          visible.push(p);
        }
      }
      if (visible.length < 2) {
        if (badgeRef.value) badgeRef.value.container.style.display = 'none';
        rafRef.value = requestAnimationFrame(draw);
        return;
      }

      // Compute + smooth Y range
      const computedRange = computeRange(visible, smoothValue, cfg.referenceLine?.value, cfg.exaggerate);
      const isWindowTransitioning = transition.startMs > 0;
      const rangeResult = updateRange(computedRange, rangeInitedRef.value, targetMinRef.value, targetMaxRef.value, displayMinRef.value, displayMaxRef.value, isWindowTransitioning, windowTransProgress, transition, adaptiveSpeed, chartH, pausedDt);
      rangeInitedRef.value = rangeResult.rangeInited;
      targetMinRef.value = rangeResult.targetMin;
      targetMaxRef.value = rangeResult.targetMax;
      displayMinRef.value = rangeResult.displayMin;
      displayMaxRef.value = rangeResult.displayMax;
      const {
        minVal,
        maxVal,
        valRange
      } = rangeResult;
      const layout: ChartLayout = {
        w,
        h,
        pad,
        chartW,
        chartH,
        leftEdge,
        rightEdge,
        minVal,
        maxVal,
        valRange,
        toX: (t: number) => pad.left + (t - leftEdge) / (rightEdge - leftEdge) * chartW,
        toY: (v: number) => pad.top + (1 - (v - minVal) / valRange) * chartH
      };

      // Momentum
      const momentum: Momentum = cfg.momentumOverride ?? detectMomentum(visible);

      // Hover + scrub
      const hoverResult = updateHoverState(hoverXRef.value, pad, w, layout, now, visible, scrubAmountRef.value, lastHoverRef.value, cfg, noMotion, leftEdge, rightEdge, chartW, dt);
      scrubAmountRef.value = hoverResult.scrubAmount;
      lastHoverRef.value = hoverResult.lastHover;
      const {
        hoverX: drawHoverX,
        hoverValue: drawHoverValue,
        hoverTime: drawHoverTime
      } = hoverResult;

      // Compute swing magnitude for particles (recent velocity / visible range)
      const lookback = Math.min(5, visible.length - 1);
      const recentDelta = lookback > 0 ? Math.abs(visible[visible.length - 1].value - visible[visible.length - 1 - lookback].value) : 0;
      const swingMagnitude = valRange > 0 ? Math.min(recentDelta / valRange, 1) : 0;

      // Draw canvas content (everything except badge)
      drawFrame(ctx, layout, cfg.palette, {
        visible,
        smoothValue,
        now,
        momentum,
        arrowState: arrowStateRef.value,
        showGrid: cfg.showGrid,
        showMomentum: cfg.showMomentum,
        showPulse: cfg.showPulse,
        showFill: cfg.showFill,
        referenceLine: cfg.referenceLine,
        hoverX: drawHoverX,
        hoverValue: drawHoverValue,
        hoverTime: drawHoverTime,
        scrubAmount: scrubAmountRef.value,
        windowSecs,
        formatValue: cfg.formatValue,
        formatTime: cfg.formatTime,
        gridState: gridStateRef.value,
        timeAxisState: timeAxisStateRef.value,
        dt,
        targetWindowSecs: cfg.windowSecs,
        tooltipY: cfg.tooltipY,
        tooltipOutline: cfg.tooltipOutline,
        orderbookData: cfg.orderbookData,
        orderbookState: cfg.orderbookData ? orderbookStateRef.value : undefined,
        particleState: cfg.degenOptions ? particleStateRef.value : undefined,
        particleOptions: cfg.degenOptions,
        swingMagnitude,
        shakeState: cfg.degenOptions ? shakeStateRef.value : undefined,
        chartReveal,
        pauseProgress,
        now_ms
      });

      // During morph (chart ↔ empty), overlay the gradient gap + text on
      // top of the morphing chart line. skipLine=true avoids double-drawing
      // the squiggly. The gap fades in smoothly as chartReveal drops.
      const bgAlpha = 1 - chartReveal;
      if (bgAlpha > 0.01 && revealTarget === 0 && !cfg.loading) {
        const bgEmptyAlpha = (1 - loadingAlpha) * bgAlpha;
        if (bgEmptyAlpha > 0.01) {
          drawEmpty(ctx, w, h, pad, cfg.palette, bgEmptyAlpha, now_ms, true, cfg.emptyText);
        }
      }

      // Badge (DOM element, floats above container)
      const badge = badgeRef.value;
      if (badge) {
        badgeYRef.value = updateBadgeDOM(badge, cfg, smoothValue, layout, momentum, badgeYRef.value, badgeColorRef.value, isWindowTransitioning, noMotion, ctx, pausedDt, chartReveal);
        // Hide badge during pause — fully fades out as pauseProgress → 1
        if (pauseProgress > 0.01 && badge.container.style.display !== 'none') {
          const base = badge.container.style.opacity ? parseFloat(badge.container.style.opacity) : 1;
          badge.container.style.opacity = String(base * (1 - pauseProgress));
        }
      }

      // --- Live value display (DOM element, updated by ref — no React re-renders) ---
      const valEl = cfg.valueDisplayRef?.value;
      if (valEl) {
        // When momentum colour is on, strip sign — colour already communicates direction
        const displayVal = cfg.valueMomentumColor ? Math.abs(smoothValue) : smoothValue;
        valEl.textContent = cfg.formatValue(displayVal);
        if (cfg.valueMomentumColor) {
          const mc = momentum === 'up' ? '#22c55e' : momentum === 'down' ? '#ef4444' : '';
          if (mc) valEl.style.color = mc;else valEl.style.removeProperty('color');
        }
      }
    } // end else (line mode)

    rafRef.value = requestAnimationFrame(draw);
  };

  // Start/stop loop
  watchLifecycle(() => {
    rafRef.value = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(rafRef.value);
  }, () => [draw]);
  return computed(() => {});
}

/**
 * Frame-rate-independent exponential lerp.
 * `speed` is the fraction approached per 16.67ms (60fps frame).
 * At lower frame rates, dt is larger so we approach more per frame.
 */
export function lerp(current: number, target: number, speed: number, dt = 16.67): number {
  // Convert per-frame speed to continuous decay factor
  const factor = 1 - Math.pow(1 - speed, dt / 16.67)
  return current + (target - current) * factor
}

import type { LivelinePoint } from '../types'

/**
 * Compute visible Y range from data points + current value.
 * Returns { min, max } with margin applied.
 */
export function computeRange(
  visible: LivelinePoint[],
  currentValue: number,
  referenceValue?: number,
  exaggerate?: boolean,
): { min: number; max: number } {
  let targetMin = Infinity
  let targetMax = -Infinity

  for (const p of visible) {
    if (p.value < targetMin) targetMin = p.value
    if (p.value > targetMax) targetMax = p.value
  }

  if (currentValue < targetMin) targetMin = currentValue
  if (currentValue > targetMax) targetMax = currentValue

  // Include reference line so it's always visible
  if (referenceValue !== undefined) {
    if (referenceValue < targetMin) targetMin = referenceValue
    if (referenceValue > targetMax) targetMax = referenceValue
  }

  const rawRange = targetMax - targetMin
  const marginFactor = exaggerate ? 0.01 : 0.12
  const minRange = rawRange * (exaggerate ? 0.02 : 0.1) || (exaggerate ? 0.04 : 0.4)

  if (rawRange < minRange) {
    const mid = (targetMin + targetMax) / 2
    targetMin = mid - minRange / 2
    targetMax = mid + minRange / 2
  } else {
    const margin = rawRange * marginFactor
    targetMin -= margin
    targetMax += margin
  }

  return { min: targetMin, max: targetMax }
}

import type { Momentum, LivelinePoint } from '../types'

/**
 * Auto-detect momentum from recent data points.
 * Only triggers during active movement — checks the last few points,
 * not the total delta over the full lookback window.
 */
export function detectMomentum(points: LivelinePoint[], lookback = 20): Momentum {
  if (points.length < 5) return 'flat'

  const start = Math.max(0, points.length - lookback)

  // Range of the full lookback for threshold calculation
  let min = Infinity
  let max = -Infinity
  for (let i = start; i < points.length; i++) {
    const v = points[i].value
    if (v < min) min = v
    if (v > max) max = v
  }
  const range = max - min
  if (range === 0) return 'flat'

  // Only look at the last 5 points for active velocity
  const tailStart = Math.max(start, points.length - 5)
  const first = points[tailStart].value
  const last = points[points.length - 1].value
  const delta = last - first

  const threshold = range * 0.12

  if (delta > threshold) return 'up'
  if (delta < -threshold) return 'down'
  return 'flat'
}

/** Get device pixel ratio, clamped to reasonable range. */
export function getDpr(): number {
  if (typeof window === 'undefined') return 1
  return Math.min(window.devicePixelRatio || 1, 3)
}

/** Apply DPR scaling to canvas context. */
export function applyDpr(
  ctx: CanvasRenderingContext2D,
  dpr: number,
  w: number,
  h: number,
) {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  ctx.clearRect(0, 0, w, h)
}

import type { LivelinePalette, ChartLayout, LivelinePoint, Momentum, ReferenceLine, OrderbookData, DegenOptions, CandlePoint } from '../types'
import { drawGrid, type GridState } from './grid'
import { drawLine } from './line'
import { drawDot, drawArrows, drawSimpleDot, drawMultiDot } from './dot'
import { drawCrosshair, drawMultiCrosshair } from './crosshair'
import type { MultiSeriesHoverEntry } from './crosshair'
import { drawReferenceLine } from './referenceLine'
import { drawTimeAxis, type TimeAxisState } from './timeAxis'
import { drawOrderbook, type OrderbookState } from './orderbook'
import { drawParticles, spawnOnSwing, type ParticleState } from './particles'
import { drawCandlesticks, drawClosePrice, drawCandleCrosshair, drawLineModeCrosshair } from './candlestick'
import { drawEmpty } from './empty'

// Constants
const SHAKE_DECAY_RATE = 0.002
const SHAKE_MIN_AMPLITUDE = 0.2
export const FADE_EDGE_WIDTH = 40
const CROSSHAIR_FADE_MIN_PX = 5

export interface ArrowState { up: number; down: number }

export interface ShakeState {
  amplitude: number  // current shake magnitude in px, decays each frame
}

export function createShakeState(): ShakeState {
  return { amplitude: 0 }
}

export interface DrawOptions {
  visible: LivelinePoint[]
  smoothValue: number
  now: number  // engine's Date.now()/1000, single timestamp for the frame
  momentum: Momentum
  arrowState: ArrowState
  showGrid: boolean
  showMomentum: boolean
  showPulse: boolean
  showFill: boolean
  referenceLine?: ReferenceLine
  hoverX: number | null
  hoverValue: number | null
  hoverTime: number | null
  scrubAmount: number // 0 = not scrubbing, 1 = fully scrubbing (lerped)
  windowSecs: number
  formatValue: (v: number) => string
  formatTime: (t: number) => string
  gridState: GridState
  timeAxisState: TimeAxisState
  dt: number // delta time in ms for frame-rate-independent lerps
  targetWindowSecs: number // final target window (stable during transitions)
  tooltipY: number
  tooltipOutline: boolean
  orderbookData?: OrderbookData
  orderbookState?: OrderbookState
  particleState?: ParticleState
  particleOptions?: DegenOptions
  swingMagnitude: number
  shakeState?: ShakeState
  chartReveal: number       // 0 = loading/morphing from center, 1 = fully revealed
  pauseProgress: number     // 0 = playing, 1 = fully paused
  now_ms: number            // performance.now() for breathing animation timing
}

/**
 * Master draw function — calls each draw module in order.
 * Mutates arrowState in place.
 */
export function drawFrame(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  opts: DrawOptions,
): void {
  // 0. Chart shake — apply offset, decay amplitude
  const shake = opts.shakeState
  let shakeX = 0
  let shakeY = 0
  if (shake && shake.amplitude > SHAKE_MIN_AMPLITUDE) {
    shakeX = (Math.random() - 0.5) * 2 * shake.amplitude
    shakeY = (Math.random() - 0.5) * 2 * shake.amplitude
    ctx.save()
    ctx.translate(shakeX, shakeY)
  }
  if (shake) {
    // Exponential decay — ~200ms of visible shake
    const decayRate = Math.pow(SHAKE_DECAY_RATE, opts.dt / 1000)
    shake.amplitude *= decayRate
    if (shake.amplitude < SHAKE_MIN_AMPLITUDE) shake.amplitude = 0
  }

  const reveal = opts.chartReveal
  const pause = opts.pauseProgress

  // Smoothstep helper for staggered reveal
  const revealRamp = (start: number, end: number) => {
    const t = Math.max(0, Math.min(1, (reveal - start) / (end - start)))
    return t * t * (3 - 2 * t)
  }

  // 1. Reference line (behind everything) — fades with reveal
  if (opts.referenceLine && reveal > 0.01) {
    ctx.save()
    if (reveal < 1) ctx.globalAlpha = reveal
    drawReferenceLine(ctx, layout, palette, opts.referenceLine)
    ctx.restore()
  }

  // 2. Grid — fades in delayed (15%–70% of reveal)
  if (opts.showGrid) {
    const gridAlpha = reveal < 1 ? revealRamp(0.15, 0.7) : 1
    if (gridAlpha > 0.01) {
      ctx.save()
      if (gridAlpha < 1) ctx.globalAlpha = gridAlpha
      drawGrid(ctx, layout, palette, opts.formatValue, opts.gridState, opts.dt)
      ctx.restore()
    }
  }

  // 2b. Orderbook (behind line) — fades with reveal
  if (opts.orderbookData && opts.orderbookState && reveal > 0.01) {
    ctx.save()
    if (reveal < 1) ctx.globalAlpha = reveal
    drawOrderbook(ctx, layout, palette, opts.orderbookData, opts.dt, opts.orderbookState, opts.swingMagnitude)
    ctx.restore()
  }

  // 3. Line + fill (with scrub dimming + reveal morphing)
  const scrubX = opts.scrubAmount > 0.05 ? opts.hoverX : null
  const pts = drawLine(ctx, layout, palette, opts.visible, opts.smoothValue, opts.now, opts.showFill, scrubX, opts.scrubAmount, reveal, opts.now_ms)

  // 4. Time axis — same timing as grid
  {
    const timeAlpha = reveal < 1 ? revealRamp(0.15, 0.7) : 1
    if (timeAlpha > 0.01) {
      ctx.save()
      if (timeAlpha < 1) ctx.globalAlpha = timeAlpha
      drawTimeAxis(ctx, layout, palette, opts.windowSecs, opts.targetWindowSecs, opts.formatTime, opts.timeAxisState, opts.dt)
      ctx.restore()
    }
  }

  if (pts && pts.length > 0) {
    const lastPt = pts[pts.length - 1]

    // 5. Dot — dims during scrub, fades in with reveal (0.3 → 1.0)
    let dotScrub = opts.scrubAmount
    if (opts.hoverX !== null && dotScrub > 0) {
      const distToLive = lastPt[0] - opts.hoverX
      const fadeStart = Math.min(80, layout.chartW * 0.3)
      dotScrub = distToLive < CROSSHAIR_FADE_MIN_PX ? 0
        : distToLive >= fadeStart ? opts.scrubAmount
        : ((distToLive - CROSSHAIR_FADE_MIN_PX) / (fadeStart - CROSSHAIR_FADE_MIN_PX)) * opts.scrubAmount
    }

    // Dot appears once shape is recognizable (reveal > 0.3)
    const dotAlpha = reveal < 0.3 ? 0 : (reveal - 0.3) / 0.7
    const showPulse = opts.showPulse && reveal > 0.6 && pause < 0.5
    if (dotAlpha > 0.01) {
      ctx.save()
      if (dotAlpha < 1) ctx.globalAlpha = dotAlpha
      drawDot(ctx, lastPt[0], lastPt[1], palette, showPulse, dotScrub, opts.now_ms)
      ctx.restore()
    }

    // 5b. Arrows — appear late in reveal (60%+), fade with pause
    if (opts.showMomentum) {
      const arrowReveal = reveal < 1 ? revealRamp(0.6, 1) : 1
      const arrowAlpha = arrowReveal * (1 - pause)
      if (arrowAlpha > 0.01) {
        ctx.save()
        if (arrowAlpha < 1) ctx.globalAlpha = arrowAlpha
        drawArrows(
          ctx, lastPt[0], lastPt[1],
          opts.momentum, palette, opts.arrowState, opts.dt, opts.now_ms,
        )
        ctx.restore()
      }
    }

    // 6. Particles — only when fully revealed
    if (opts.particleState && reveal > 0.9) {
      const burstIntensity = spawnOnSwing(
        opts.particleState, opts.momentum, lastPt[0], lastPt[1],
        opts.swingMagnitude, palette.line, opts.dt, opts.particleOptions,
      )
      if (burstIntensity > 0 && shake) {
        shake.amplitude = (3 + opts.swingMagnitude * 4) * burstIntensity
      }
      drawParticles(ctx, opts.particleState, opts.dt)
    }
  }

  // 7. Left edge fade — gradient erase
  const fadeW = FADE_EDGE_WIDTH
  ctx.save()
  ctx.globalCompositeOperation = 'destination-out'
  const fadeGrad = ctx.createLinearGradient(layout.pad.left, 0, layout.pad.left + fadeW, 0)
  fadeGrad.addColorStop(0, 'rgba(0, 0, 0, 1)')
  fadeGrad.addColorStop(1, 'rgba(0, 0, 0, 0)')
  ctx.fillStyle = fadeGrad
  ctx.fillRect(0, 0, layout.pad.left + fadeW, layout.h)
  ctx.restore()

  // 8. Crosshair — fade out well before reaching live dot
  if (opts.hoverX !== null && opts.hoverValue !== null && opts.hoverTime !== null && pts && pts.length > 0) {
    const lastPt = pts[pts.length - 1]
    const distToLive = lastPt[0] - opts.hoverX
    const fadeStart = Math.min(80, layout.chartW * 0.3)
    const scrubOpacity = distToLive < CROSSHAIR_FADE_MIN_PX ? 0
      : distToLive >= fadeStart ? opts.scrubAmount
      : ((distToLive - CROSSHAIR_FADE_MIN_PX) / (fadeStart - CROSSHAIR_FADE_MIN_PX)) * opts.scrubAmount

    if (scrubOpacity > 0.01) {
      drawCrosshair(
        ctx, layout, palette,
        opts.hoverX, opts.hoverValue, opts.hoverTime,
        opts.formatValue, opts.formatTime,
        scrubOpacity,
        opts.tooltipY,
        lastPt[0], // liveDotX — tooltip right edge stops here
        opts.tooltipOutline,
      )
    }
  }

  // Restore shake translate
  if (shake && (shakeX !== 0 || shakeY !== 0)) {
    ctx.restore()
  }
}

// ─── Multi-series draw orchestration ──────────────────────────────────────

export interface MultiSeriesEntry {
  visible: LivelinePoint[]
  smoothValue: number
  palette: LivelinePalette
  label?: string
  alpha?: number  // series visibility alpha (0 = hidden, 1 = visible)
}

export interface MultiSeriesDrawOptions {
  series: MultiSeriesEntry[]
  now: number
  showGrid: boolean
  showPulse: boolean
  referenceLine?: ReferenceLine
  hoverX: number | null
  hoverTime: number | null
  hoverEntries: MultiSeriesHoverEntry[]
  scrubAmount: number
  windowSecs: number
  formatValue: (v: number) => string
  formatTime: (t: number) => string
  gridState: GridState
  timeAxisState: TimeAxisState
  dt: number
  targetWindowSecs: number
  tooltipY: number
  tooltipOutline: boolean
  chartReveal: number
  pauseProgress: number
  now_ms: number
  /** Primary palette (from first series) for grid/axis/crosshair colors */
  primaryPalette: LivelinePalette
}

/**
 * Multi-series draw function — draws multiple overlapping lines sharing the same axes.
 * No fill, no momentum arrows, no badge (those are per-chart concerns handled by the engine).
 */
export function drawMultiFrame(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  opts: MultiSeriesDrawOptions,
): void {
  const palette = opts.primaryPalette
  const reveal = opts.chartReveal

  const revealRamp = (start: number, end: number) => {
    const t = Math.max(0, Math.min(1, (reveal - start) / (end - start)))
    return t * t * (3 - 2 * t)
  }

  // 1. Reference line
  if (opts.referenceLine && reveal > 0.01) {
    ctx.save()
    if (reveal < 1) ctx.globalAlpha = reveal
    drawReferenceLine(ctx, layout, palette, opts.referenceLine)
    ctx.restore()
  }

  // 2. Grid
  if (opts.showGrid) {
    const gridAlpha = reveal < 1 ? revealRamp(0.15, 0.7) : 1
    if (gridAlpha > 0.01) {
      ctx.save()
      if (gridAlpha < 1) ctx.globalAlpha = gridAlpha
      drawGrid(ctx, layout, palette, opts.formatValue, opts.gridState, opts.dt)
      ctx.restore()
    }
  }

  // 3. Draw each series line (back to front, no fill, with scrub dimming)
  // During reverse morph, secondary lines fade out so only one remains at
  // chartReveal=0 — prevents alpha compounding from multiple overlapping strokes
  // looking brighter than the single standalone loading squiggly.
  const scrubX = opts.scrubAmount > 0.05 ? opts.hoverX : null
  const allPts: { pts: [number, number][]; palette: LivelinePalette; label?: string; alpha: number }[] = []
  for (let si = 0; si < opts.series.length; si++) {
    const s = opts.series[si]
    const seriesAlpha = s.alpha ?? 1
    const secondaryFade = (si > 0 && reveal < 1) ? Math.min(1, reveal * 2) : 1
    const combinedAlpha = secondaryFade * seriesAlpha
    if (combinedAlpha < 0.01) continue
    ctx.save()
    if (combinedAlpha < 1) ctx.globalAlpha = combinedAlpha
    const pts = drawLine(
      ctx, layout, s.palette, s.visible, s.smoothValue, opts.now,
      false, // no fill
      scrubX, opts.scrubAmount,
      reveal, opts.now_ms,
    )
    ctx.restore()
    if (pts && pts.length > 0) {
      allPts.push({ pts, palette: s.palette, label: s.label, alpha: seriesAlpha })
    }
  }

  // 4. Time axis
  {
    const timeAlpha = reveal < 1 ? revealRamp(0.15, 0.7) : 1
    if (timeAlpha > 0.01) {
      ctx.save()
      if (timeAlpha < 1) ctx.globalAlpha = timeAlpha
      drawTimeAxis(ctx, layout, palette, opts.windowSecs, opts.targetWindowSecs, opts.formatTime, opts.timeAxisState, opts.dt)
      ctx.restore()
    }
  }

  // 5. Endpoint dots + labels for each series
  // Dots stay at reveal-based alpha only (no scrub dimming) — matching
  // single-series where drawDot keeps inner dot at full baseAlpha
  if (reveal > 0.3 && allPts.length > 0) {
    const dotAlpha = (reveal - 0.3) / 0.7
    const showPulse = opts.showPulse && reveal > 0.6 && opts.pauseProgress < 0.5

    for (const entry of allPts) {
      if (entry.alpha < 0.01) continue
      const lastPt = entry.pts[entry.pts.length - 1]

      ctx.save()
      ctx.globalAlpha = dotAlpha * entry.alpha

      // Use pulsing dot when enabled and series is mostly visible
      if (showPulse && entry.alpha > 0.5) {
        drawMultiDot(ctx, lastPt[0], lastPt[1], entry.palette.line, true, opts.now_ms, 3)
      } else {
        drawSimpleDot(ctx, lastPt[0], lastPt[1], entry.palette.line, 3)
      }

      // Label at endpoint (right of dot — layout reserves space via labelReserve)
      if (entry.label) {
        ctx.font = '600 10px -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif'
        ctx.textAlign = 'left'
        ctx.fillStyle = entry.palette.line
        ctx.fillText(entry.label, lastPt[0] + 6, lastPt[1] + 3.5)
      }
      ctx.restore()
    }
  }

  // 6. Left edge fade
  ctx.save()
  ctx.globalCompositeOperation = 'destination-out'
  const fadeGrad = ctx.createLinearGradient(layout.pad.left, 0, layout.pad.left + FADE_EDGE_WIDTH, 0)
  fadeGrad.addColorStop(0, 'rgba(0, 0, 0, 1)')
  fadeGrad.addColorStop(1, 'rgba(0, 0, 0, 0)')
  ctx.fillStyle = fadeGrad
  ctx.fillRect(0, 0, layout.pad.left + FADE_EDGE_WIDTH, layout.h)
  ctx.restore()

  // 7. Multi-series crosshair — fade out near live dots (same logic as single-series)
  if (opts.hoverX !== null && opts.hoverTime !== null && opts.hoverEntries.length > 0 && allPts.length > 0 && opts.scrubAmount > 0.01) {
    // Find rightmost live dot X (skip hidden series)
    let maxLiveDotX = 0
    for (const entry of allPts) {
      if (entry.alpha < 0.01) continue
      const lastX = entry.pts[entry.pts.length - 1][0]
      if (lastX > maxLiveDotX) maxLiveDotX = lastX
    }

    const distToLive = maxLiveDotX - opts.hoverX
    const fadeStart = Math.min(80, layout.chartW * 0.3)
    const scrubOpacity = distToLive < CROSSHAIR_FADE_MIN_PX ? 0
      : distToLive >= fadeStart ? opts.scrubAmount
      : ((distToLive - CROSSHAIR_FADE_MIN_PX) / (fadeStart - CROSSHAIR_FADE_MIN_PX)) * opts.scrubAmount

    if (scrubOpacity > 0.01) {
      drawMultiCrosshair(
        ctx, layout, palette,
        opts.hoverX, opts.hoverTime,
        opts.hoverEntries,
        opts.formatValue, opts.formatTime,
        scrubOpacity,
        opts.tooltipY,
        opts.tooltipOutline,
        maxLiveDotX,
      )
    }
  }
}

// ─── Candlestick draw orchestration ────────────────────────────────────────

export interface CandleDrawOptions {
  candles: CandlePoint[]
  displayCandleWidth: number
  oldCandles: CandlePoint[]
  oldWidth: number
  morphT: number                    // candle width transition progress (-1 = none)
  liveCandle?: CandlePoint
  /** Pre-blend live candle for the dashed close-price line (unaffected by line mode morph) */
  closePriceCandle?: CandlePoint
  liveTime: number
  liveBirthAlpha: number
  liveBullBlend: number
  lineModeProg: number
  chartReveal: number
  now_ms: number
  now: number
  pauseProgress: number
  showGrid: boolean
  scrubAmount: number
  hoverX: number | null
  hoverValue: number | null
  hoverTime: number | null
  hoveredCandle: CandlePoint | null
  formatValue: (v: number) => string
  formatTime: (t: number) => string
  gridState: GridState
  timeAxisState: TimeAxisState
  dt: number
  targetWindowSecs: number
  tooltipY: number
  tooltipOutline: boolean
  // Line data — drawLine handles morphY, alpha, color, dot position
  lineVisible: LivelinePoint[]
  lineSmoothValue: number
  emptyText?: string
  loadingAlpha: number
  showEmptyOverlay: boolean  // true only when collapsing to empty (not loading, not forward morph)
}

/**
 * Candlestick draw orchestrator — calls each draw module in the correct
 * order for candle mode. Pure drawing function, no state management.
 */
export function drawCandleFrame(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  opts: CandleDrawOptions,
): void {
  const { w, h, pad, chartW, chartH } = layout
  const reveal = opts.chartReveal

  // When fully in line mode, delegate entirely to drawLine (same path as
  // drawFrame) so transitions are visually identical to line mode.
  const fullLineMode = opts.lineModeProg >= 0.99

  // Line presence (lp): during the reveal, the morph line smoothly
  // transforms from the loading squiggly into data positions. In candle
  // mode it fades much faster (cubed) so candles become dominant early
  // and the morphing line never looks like a "line chart."
  const revealLine = fullLineMode
    ? (1 - reveal)
    : (1 - reveal) * (1 - reveal) * (1 - reveal)
  const lp = Math.max(opts.lineModeProg, revealLine)

  // colorBlend: when reveal drives lp, force grey (loading squiggly color).
  // When the user's lineModeProg drives lp, use accent color.
  const colorBlend = lp > 0.001 ? opts.lineModeProg / lp : 1

  // Smoothstep helper for staggered reveal
  const revealRamp = (start: number, end: number) => {
    const t = Math.max(0, Math.min(1, (reveal - start) / (end - start)))
    return t * t * (3 - 2 * t)
  }

  // 1. Grid — fades in (25%–60% of reveal)
  const gridAlpha = revealRamp(0.25, 0.6)
  if (opts.showGrid && gridAlpha > 0.01) {
    ctx.save()
    if (gridAlpha < 1) ctx.globalAlpha = gridAlpha
    drawGrid(ctx, layout, palette, opts.formatValue, opts.gridState, opts.dt)
    ctx.restore()
  }

  // 2. Line — morph line that transforms from loading squiggly into data.
  //    Returns pts for dot position.
  let linePts: [number, number][] | undefined
  if (lp > 0.01 && opts.lineVisible.length >= 2) {
    const scrubX = opts.scrubAmount > 0.05 ? opts.hoverX : null
    ctx.save()
    ctx.globalAlpha = lp
    linePts = drawLine(
      ctx, layout, palette, opts.lineVisible, opts.lineSmoothValue, opts.now,
      opts.lineModeProg > 0.01, scrubX, opts.scrubAmount, opts.chartReveal, opts.now_ms,
      colorBlend, !fullLineMode,
      opts.lineModeProg, // fillScale — fill fades smoothly with line mode transition
    )
    ctx.restore()
  }

  // 3. Close price line — fades in (40%–80% of reveal)
  //    Uses closePriceCandle (pre-blend) so the dashed line isn't affected
  //    by line mode morph or OHLC collapse.
  const closeAlpha = revealRamp(0.4, 0.8)
  const closeSource = opts.closePriceCandle ?? opts.liveCandle
  if (closeSource && closeAlpha > 0.01) {
    // Candle-colored close line (fades out with lineModeProg)
    if (lp < 0.99) {
      ctx.save()
      ctx.globalAlpha = closeAlpha * (1 - lp)
      drawClosePrice(ctx, layout, palette, closeSource, opts.scrubAmount, opts.liveBullBlend)
      ctx.restore()
    }
    // Accent-colored dash line (fades in with lineModeProg)
    // Skip when fully in line mode — drawLine draws its own morphing dash
    if (lp > 0.01 && !fullLineMode) {
      const dashY = layout.toY(closeSource.close)
      if (dashY >= pad.top && dashY <= h - pad.bottom) {
        ctx.save()
        ctx.setLineDash([4, 4])
        ctx.strokeStyle = palette.dashLine
        ctx.lineWidth = 1
        ctx.globalAlpha = closeAlpha * lp * (1 - opts.scrubAmount * 0.2)
        ctx.beginPath()
        ctx.moveTo(pad.left, dashY)
        ctx.lineTo(w - pad.right, dashY)
        ctx.stroke()
        ctx.setLineDash([])
        ctx.restore()
      }
    }
  }

  // 4. Candles — alpha = chartReveal * (1 - lp)
  //    During reveal, OHLC collapses toward close so candle bodies shrink
  //    into thin lines before fading out (or grow from thin lines on appear).
  const candleAlpha = opts.chartReveal * (1 - lp)
  if (candleAlpha > 0.01) {
    // OHLC expansion uses smoothstep on reveal — this keeps shape and alpha
    // in sync (at 50% visible, candles are ~50% expanded rather than flat).
    const ohlcScale = reveal * reveal * (3 - 2 * reveal)
    const collapseC = (c: CandlePoint): CandlePoint =>
      ohlcScale >= 0.99 ? c : ({
        time: c.time,
        open: c.close + (c.open - c.close) * ohlcScale,
        high: c.close + (c.high - c.close) * ohlcScale,
        low: c.close + (c.low - c.close) * ohlcScale,
        close: c.close,
      })
    const revealCandles = ohlcScale < 0.99 ? opts.candles.map(collapseC) : opts.candles
    const revealOld = ohlcScale < 0.99 && opts.oldCandles.length > 0
      ? opts.oldCandles.map(collapseC) : opts.oldCandles

    ctx.save()
    ctx.beginPath()
    ctx.rect(pad.left - 1, pad.top, chartW + 2, chartH)
    ctx.clip()
    const accentCol = lp > 0.01 ? palette.line : undefined
    if (opts.morphT >= 0 && revealOld.length > 0) {
      ctx.globalAlpha = (1 - opts.morphT) * candleAlpha
      drawCandlesticks(
        ctx, layout, revealOld, opts.oldWidth,
        -1, opts.now_ms, opts.hoverX ?? 0, opts.scrubAmount,
        1, -1, accentCol, lp,
      )
      ctx.globalAlpha = opts.morphT * candleAlpha
      drawCandlesticks(
        ctx, layout, revealCandles, opts.displayCandleWidth,
        opts.liveCandle?.time ?? -1, opts.now_ms,
        opts.hoverX ?? 0, opts.scrubAmount,
        opts.liveBirthAlpha, opts.liveBullBlend,
        accentCol, lp,
      )
      ctx.globalAlpha = 1
    } else {
      if (candleAlpha < 1) ctx.globalAlpha = candleAlpha
      drawCandlesticks(
        ctx, layout, revealCandles, opts.displayCandleWidth,
        opts.liveCandle?.time ?? -1, opts.now_ms,
        opts.hoverX ?? 0, opts.scrubAmount,
        opts.liveBirthAlpha, opts.liveBullBlend,
        accentCol, lp,
      )
    }
    ctx.restore()
  }

  // 5. Live dot — position from drawLine's returned pts (same as drawFrame).
  if (lp > 0.5 && linePts && linePts.length > 0 && reveal > 0.3) {
    const lastPt = linePts[linePts.length - 1]
    const dotAlpha = ((lp - 0.5) * 2) * ((reveal - 0.3) / 0.7)
    const showPulse = lp > 0.8 && reveal > 0.6
    if (dotAlpha > 0.01) {
      ctx.save()
      ctx.globalAlpha = dotAlpha
      drawDot(ctx, lastPt[0], lastPt[1], palette, showPulse, opts.scrubAmount, opts.now_ms)
      ctx.restore()
    }
  }

  // 6. Time axis — fades in (25%–60% of reveal)
  const timeAlpha = revealRamp(0.25, 0.6)
  if (timeAlpha > 0.01) {
    ctx.save()
    if (timeAlpha < 1) ctx.globalAlpha = timeAlpha
    drawTimeAxis(ctx, layout, palette, opts.targetWindowSecs, opts.targetWindowSecs, opts.formatTime, opts.timeAxisState, opts.dt)
    ctx.restore()
  }

  // 7. Left edge fade — gradient erase
  ctx.save()
  ctx.globalCompositeOperation = 'destination-out'
  const fadeGrad = ctx.createLinearGradient(pad.left, 0, pad.left + FADE_EDGE_WIDTH, 0)
  fadeGrad.addColorStop(0, 'rgba(0, 0, 0, 1)')
  fadeGrad.addColorStop(1, 'rgba(0, 0, 0, 0)')
  ctx.fillStyle = fadeGrad
  ctx.fillRect(0, 0, pad.left + FADE_EDGE_WIDTH, h)
  ctx.restore()

  // 8. Reverse morph empty overlay — only when collapsing to empty state
  //    (not during forward morph or loading), matching line mode's
  //    `revealTarget === 0 && !cfg.loading` guard.
  if (opts.showEmptyOverlay) {
    const bgAlpha = 1 - opts.chartReveal
    if (bgAlpha > 0.01) {
      const bgEmptyAlpha = (1 - opts.loadingAlpha) * bgAlpha
      if (bgEmptyAlpha > 0.01) {
        drawEmpty(ctx, w, h, pad, palette, bgEmptyAlpha, opts.now_ms, true, opts.emptyText)
      }
    }
  }

  // 9. Crosshair — only when mostly revealed (70%+)
  if (opts.chartReveal > 0.7 && opts.hoveredCandle && opts.hoverX !== null && opts.scrubAmount > 0.01) {
    if (opts.lineModeProg > 0.5) {
      drawLineModeCrosshair(
        ctx, layout, palette,
        opts.hoverX, opts.hoveredCandle.close, opts.hoverTime ?? 0,
        opts.formatValue, opts.formatTime,
        opts.scrubAmount,
      )
    } else {
      drawCandleCrosshair(
        ctx, layout, palette,
        opts.hoverX, opts.hoveredCandle, opts.hoverTime ?? 0,
        opts.formatValue, opts.formatTime,
        opts.scrubAmount,
      )
    }
  }
}

import type { LivelinePalette, ChartLayout } from '../types'
import { lerp } from '../math/lerp'

/**
 * Pick a nice interval using TradingView's cycling divisor approach.
 * Hysteresis: once chosen, sticks until spacing falls outside [0.5×, 4×] of minGap.
 */
function pickInterval(
  valRange: number,
  pxPerUnit: number,
  minGap: number,
  prev: number,
): number {
  if (prev > 0) {
    const px = prev * pxPerUnit
    if (px >= minGap * 0.5 && px <= minGap * 4) return prev
  }

  const divisorSets = [[2, 2.5, 2], [2, 2, 2.5], [2.5, 2, 2]]
  let best = Infinity
  for (const divs of divisorSets) {
    let span = Math.pow(10, Math.ceil(Math.log10(valRange)))
    let i = 0
    while (span / divs[i % 3] * pxPerUnit >= minGap) {
      span /= divs[i % 3]
      i++
    }
    if (span < best) best = span
  }
  return best === Infinity ? valRange / 5 : best
}

/** Float-safe divisibility check. */
function divisible(val: number, interval: number): boolean {
  const ratio = val / interval
  return Math.abs(ratio - Math.round(ratio)) < 0.01
}

/** Persistent state — interval hysteresis + per-label alpha smoothing. */
export interface GridState {
  interval: number
  labels: Map<number, number> // key → alpha
}

const FADE_IN = 0.18
const FADE_OUT = 0.12

export function drawGrid(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  formatValue: (v: number) => string,
  state: GridState,
  dt: number,
) {
  const { w, h, pad, valRange, minVal, maxVal, toY } = layout
  const chartH = h - pad.top - pad.bottom
  if (chartH <= 0 || valRange <= 0) return
  const pxPerUnit = chartH / valRange

  // Coarse interval: always-visible anchor labels
  const coarse = pickInterval(valRange, pxPerUnit, 36, state.interval)
  state.interval = coarse

  // Fine interval: fills the gaps between coarse labels
  const fine = coarse / 2
  const finePx = fine * pxPerUnit

  // Target alpha for fine labels — hide when cramped, fade in with space
  const fineTarget = finePx < 40 ? 0 : finePx >= 60 ? 1 : (finePx - 40) / 20

  // Edge fade
  const fadeZone = 32
  const edgeAlpha = (y: number): number => {
    const fromEdge = Math.min(y - pad.top, h - pad.bottom - y)
    if (fromEdge >= fadeZone) return 1
    if (fromEdge <= 0) return 0
    return fromEdge / fadeZone
  }

  // --- Phase 1: compute target alpha for every current grid label ---
  const targets = new Map<number, number>()
  const first = Math.ceil(minVal / fine) * fine
  for (let val = first; val <= maxVal; val += fine) {
    const y = toY(val)
    if (y < pad.top - 2 || y > h - pad.bottom + 2) continue
    const isCoarse = divisible(val, coarse)
    const target = (isCoarse ? 1 : fineTarget) * edgeAlpha(y)
    const key = Math.round(val * 1000)
    targets.set(key, target)
  }

  // --- Phase 2: update all tracked label alphas ---
  for (const [key, alpha] of state.labels) {
    const target = targets.get(key) ?? 0
    const speed = target >= alpha ? FADE_IN : FADE_OUT
    let next = lerp(alpha, target, speed, dt)
    if (Math.abs(next - target) < 0.02) next = target
    if (next < 0.01 && target === 0) {
      state.labels.delete(key)
    } else {
      state.labels.set(key, next)
    }
  }

  // New labels not yet in state
  for (const [key, target] of targets) {
    if (!state.labels.has(key)) {
      state.labels.set(key, target * FADE_IN)
    }
  }

  // --- Phase 3: draw ---
  const baseAlpha = ctx.globalAlpha
  ctx.setLineDash([1, 3])
  ctx.lineWidth = 1
  ctx.font = palette.labelFont
  ctx.textAlign = 'left'

  for (const [key, alpha] of state.labels) {
    if (alpha < 0.02) continue

    const val = key / 1000
    const y = toY(val)
    if (y < pad.top - 10 || y > h - pad.bottom + 10) continue

    ctx.save()
    ctx.globalAlpha = baseAlpha * alpha

    ctx.strokeStyle = palette.gridLine
    ctx.beginPath()
    ctx.moveTo(pad.left, y)
    ctx.lineTo(w - pad.right, y)
    ctx.stroke()

    ctx.fillStyle = palette.gridLabel
    ctx.fillText(formatValue(val), w - pad.right + 8, y + 4)

    ctx.restore()
  }

  ctx.setLineDash([])
}

import type { LivelinePalette, ChartLayout, LivelinePoint } from '../types'
import { drawSpline } from '../math/spline'
import { loadingY, loadingBreath, LOADING_AMPLITUDE_RATIO, LOADING_SCROLL_SPEED } from './loadingShape'

/** Parse a CSS color to [r, g, b, a]. Handles hex, rgb(), rgba(). */
function parseRgba(color: string): [number, number, number, number] {
  const hex = color.match(/^#([0-9a-f]{3,8})$/i)
  if (hex) {
    let h = hex[1]
    if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2]
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16), 1]
  }
  const rgba = color.match(/rgba\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*([\d.]+)/)
  if (rgba) return [+rgba[1], +rgba[2], +rgba[3], +rgba[4]]
  const rgb = color.match(/rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/)
  if (rgb) return [+rgb[1], +rgb[2], +rgb[3], 1]
  return [128, 128, 128, 1]
}

/** Lerp between two CSS colors including alpha. Handles hex, rgb(), rgba(). */
function blendColor(c1: string, c2: string, t: number): string {
  if (t <= 0) return c1
  if (t >= 1) return c2
  const [r1, g1, b1, a1] = parseRgba(c1)
  const [r2, g2, b2, a2] = parseRgba(c2)
  const r = Math.round(r1 + (r2 - r1) * t)
  const g = Math.round(g1 + (g2 - g1) * t)
  const b = Math.round(b1 + (b2 - b1) * t)
  const a = a1 + (a2 - a1) * t
  if (a >= 0.995) return `rgb(${r},${g},${b})`
  return `rgba(${r},${g},${b},${a.toFixed(3)})`
}

/** Draw the fill gradient + stroke line for a set of points. */
function renderCurve(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  pts: [number, number][],
  showFill: boolean,
  lineAlpha: number = 1,
  fillAlpha: number = 1,
  strokeColor?: string,
) {
  const { h, pad } = layout
  const baseAlpha = ctx.globalAlpha

  if (showFill && fillAlpha > 0.01) {
    ctx.globalAlpha = baseAlpha * fillAlpha
    const grad = ctx.createLinearGradient(0, pad.top, 0, h - pad.bottom)
    grad.addColorStop(0, palette.fillTop)
    grad.addColorStop(1, palette.fillBottom)
    ctx.beginPath()
    ctx.moveTo(pts[0][0], h - pad.bottom)
    ctx.lineTo(pts[0][0], pts[0][1])
    drawSpline(ctx, pts)
    ctx.lineTo(pts[pts.length - 1][0], h - pad.bottom)
    ctx.closePath()
    ctx.fillStyle = grad
    ctx.fill()
  }

  ctx.globalAlpha = baseAlpha * lineAlpha
  ctx.beginPath()
  ctx.moveTo(pts[0][0], pts[0][1])
  drawSpline(ctx, pts)
  ctx.strokeStyle = strokeColor ?? palette.line
  ctx.lineWidth = palette.lineWidth
  ctx.lineJoin = 'round'
  ctx.lineCap = 'round'
  ctx.stroke()
  ctx.globalAlpha = baseAlpha
}

export function drawLine(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  visible: LivelinePoint[],
  smoothValue: number,
  now: number,
  showFill: boolean,
  scrubX: number | null,
  scrubAmount: number = 0,
  chartReveal: number = 1,
  now_ms: number = 0,
  colorBlend: number = 1,
  skipDashLine: boolean = false,
  fillScale: number = 1,
) {
  const { h, pad, toX, toY, chartW, chartH } = layout
  const incomingAlpha = ctx.globalAlpha

  // Build screen-space points: all historical data stays stable,
  // but the LAST data point uses smoothValue for its Y (so big jumps
  // animate smoothly instead of snapping). Its X stays at the original
  // data time (stable, no per-frame drift — this is what killed jitter).
  // Then append the live tip at (now, smoothValue).
  // Y coordinates are clamped to chart bounds so the line hugs the edge
  // during range transitions instead of getting hard-clipped.
  const yMin = pad.top
  const yMax = h - pad.bottom
  const clampY = (y: number) => Math.max(yMin, Math.min(yMax, y))

  // During reveal, morph Y positions from the loading squiggly shape toward real data.
  // At chartReveal=0 the chart line traces the exact same squiggly as drawLoading/drawEmpty.
  // Center-out: the center of the chart resolves first, edges last, so the data
  // line appears to bloom outward from the middle.
  const centerY = pad.top + chartH / 2
  const amplitude = chartH * LOADING_AMPLITUDE_RATIO
  const scroll = now_ms * LOADING_SCROLL_SPEED
  const morphY = chartReveal < 1
    ? (rawY: number, x: number) => {
        const t = Math.max(0, Math.min(1, (x - pad.left) / chartW))
        const centerDist = Math.abs(t - 0.5) * 2 // 0 at center, 1 at edges
        const localReveal = Math.max(0, Math.min(1, (chartReveal - centerDist * 0.4) / 0.6))
        const baseY = loadingY(t, centerY, amplitude, scroll)
        return baseY + (rawY - baseY) * localReveal
      }
    : (rawY: number, _x: number) => rawY

  const pts: [number, number][] = visible.map((p, i) => {
    const x = toX(p.time)
    const y = i === visible.length - 1
      ? morphY(clampY(toY(smoothValue)), x)
      : morphY(clampY(toY(p.value)), x)
    return [x, y]
  })
  // Tip X: at reveal=0 extends to full chart width (matching loading/empty line),
  // at reveal=1 sits at the live dot position. Smooth morph between.
  const liveTipX = toX(now)
  const fullRightX = pad.left + chartW
  const tipX = chartReveal < 1
    ? liveTipX + (fullRightX - liveTipX) * (1 - chartReveal)
    : liveTipX
  pts.push([tipX, morphY(clampY(toY(smoothValue)), tipX)])

  if (pts.length < 2) return

  // Reveal alphas: at reveal=0, line matches loading/empty brightness (shared breath).
  // As reveal increases, line ramps to full. Fill fades in with reveal.
  let lineAlpha = 1
  let fillAlpha = fillScale
  if (chartReveal < 1) {
    const breath = loadingBreath(now_ms)
    lineAlpha = breath + (1 - breath) * chartReveal
    fillAlpha = chartReveal * fillScale
  }

  // Blend line color: grey at reveal=0, accent by reveal≈0.3.
  // colorBlend scales the accent mix — 0 forces grey (used during reverse morph
  // so the line fades to the loading squiggly color instead of flashing blue).
  const colorT = Math.min(1, chartReveal * 3) * colorBlend
  const strokeColor = (chartReveal < 1 || colorBlend < 1)
    ? blendColor(palette.gridLabel, palette.line, colorT)
    : undefined

  const isScrubbing = scrubX !== null

  // Clip line + fill to chart area — during big value jumps the range
  // lerps smoothly so the line may extend beyond the chart bounds.
  // Clipping keeps it tidy while the range catches up.
  ctx.save()
  ctx.beginPath()
  ctx.rect(pad.left - 1, pad.top, chartW + 2, chartH)
  ctx.clip()

  if (isScrubbing) {
    // Full-opacity portion: clipped to LEFT of scrub point
    ctx.save()
    ctx.beginPath()
    ctx.rect(0, 0, scrubX!, h)
    ctx.clip()
    renderCurve(ctx, layout, palette, pts, showFill, lineAlpha, fillAlpha, strokeColor)
    ctx.restore()

    // Dimmed portion: clipped to RIGHT of scrub point
    ctx.save()
    ctx.beginPath()
    ctx.rect(scrubX!, 0, layout.w - scrubX!, h)
    ctx.clip()
    ctx.globalAlpha = incomingAlpha * (1 - scrubAmount * 0.6)
    renderCurve(ctx, layout, palette, pts, showFill, lineAlpha, fillAlpha, strokeColor)
    ctx.restore()
  } else {
    renderCurve(ctx, layout, palette, pts, showFill, lineAlpha, fillAlpha, strokeColor)
  }

  // Restore from chart-area clip
  ctx.restore()

  // Dashed current-price line — morphs from center during reveal (fades in late,
  // so the center-vs-squiggly difference is imperceptible by the time it's visible)
  if (!skipDashLine) {
    const realCurrentY = Math.max(pad.top, Math.min(h - pad.bottom, toY(smoothValue)))
    const currentY = chartReveal < 1
      ? centerY + (realCurrentY - centerY) * chartReveal
      : realCurrentY
    ctx.setLineDash([4, 4])
    ctx.strokeStyle = palette.dashLine
    ctx.lineWidth = 1
    const dashBase = isScrubbing ? 1 - scrubAmount * 0.2 : 1
    ctx.globalAlpha = incomingAlpha * (chartReveal < 1 ? dashBase * chartReveal : dashBase)
    ctx.beginPath()
    ctx.moveTo(pad.left, currentY)
    ctx.lineTo(layout.w - pad.right, currentY)
    ctx.stroke()
    ctx.setLineDash([])
  }
  ctx.globalAlpha = incomingAlpha

  // Clamp last point Y so dot stays within canvas (not chart area).
  // The dot outer circle is 6.5px + shadow — 10px margin keeps it visible.
  const last = pts[pts.length - 1]
  last[1] = Math.max(10, Math.min(h - 10, last[1]))

  return pts
}

/**
 * Fritsch-Carlson monotone cubic interpolation.
 * Guarantees no overshoots — the curve never exceeds local min/max.
 * Used by Chart.js (monotone mode) and D3 (curveMonotoneX).
 *
 * Continues from current ctx position — caller must moveTo first point.
 */
export function drawSpline(
  ctx: CanvasRenderingContext2D,
  pts: [number, number][],
) {
  if (pts.length < 2) return
  if (pts.length === 2) {
    ctx.lineTo(pts[1][0], pts[1][1])
    return
  }

  const n = pts.length

  // 1. Compute secant slopes (delta) between consecutive points
  const delta: number[] = new Array(n - 1)
  const h: number[] = new Array(n - 1) // x-intervals
  for (let i = 0; i < n - 1; i++) {
    h[i] = pts[i + 1][0] - pts[i][0]
    delta[i] = h[i] === 0 ? 0 : (pts[i + 1][1] - pts[i][1]) / h[i]
  }

  // 2. Initial tangent estimates
  const m: number[] = new Array(n)
  m[0] = delta[0]
  m[n - 1] = delta[n - 2]
  for (let i = 1; i < n - 1; i++) {
    if (delta[i - 1] * delta[i] <= 0) {
      // Sign change or zero — tangent must be zero for monotonicity
      m[i] = 0
    } else {
      m[i] = (delta[i - 1] + delta[i]) / 2
    }
  }

  // 3. Fritsch-Carlson constraint: alpha^2 + beta^2 <= 9
  for (let i = 0; i < n - 1; i++) {
    if (delta[i] === 0) {
      // Flat segment — zero both endpoint tangents
      m[i] = 0
      m[i + 1] = 0
    } else {
      const alpha = m[i] / delta[i]
      const beta = m[i + 1] / delta[i]
      const s2 = alpha * alpha + beta * beta
      if (s2 > 9) {
        const s = 3 / Math.sqrt(s2)
        m[i] = s * alpha * delta[i]
        m[i + 1] = s * beta * delta[i]
      }
    }
  }

  // 4. Draw bezier curves using tangents as control points
  for (let i = 0; i < n - 1; i++) {
    const hi = h[i]
    ctx.bezierCurveTo(
      pts[i][0] + hi / 3,
      pts[i][1] + m[i] * hi / 3,
      pts[i + 1][0] - hi / 3,
      pts[i + 1][1] - m[i + 1] * hi / 3,
      pts[i + 1][0],
      pts[i + 1][1],
    )
  }
}

/**
 * Shared squiggly line shape and breathing alpha used by both the loading
 * state and the chart morph transition. Keeping it in one place guarantees
 * the loading line and chart's starting shape + brightness are identical.
 */

export const LOADING_AMPLITUDE_RATIO = 0.07
export const LOADING_SCROLL_SPEED = 0.001

/**
 * Returns the squiggly Y position for a loading line.
 * @param t         Normalized x position across chart width (0–1)
 * @param centerY   Vertical center of the chart area
 * @param amplitude Wave height in pixels (chartH * LOADING_AMPLITUDE_RATIO)
 * @param scroll    Time-based scroll offset (now_ms * LOADING_SCROLL_SPEED)
 */
export function loadingY(
  t: number,
  centerY: number,
  amplitude: number,
  scroll: number,
): number {
  return centerY + amplitude * (
    Math.sin(t * 9.4 + scroll) * 0.55 +
    Math.sin(t * 15.7 + scroll * 1.3) * 0.3 +
    Math.sin(t * 4.2 + scroll * 0.7) * 0.15
  )
}

/** Breathing alpha for the loading line and chart line at reveal=0. */
export function loadingBreath(now_ms: number): number {
  return 0.22 + 0.08 * Math.sin(now_ms / 1200 * Math.PI)
}

import type { Momentum, LivelinePalette } from '../types'
import type { ArrowState } from './index'
import { parseColorRgb } from '../theme'
import { lerp } from '../math/lerp'

const PULSE_INTERVAL = 1500
const PULSE_DURATION = 900

function lerpColor(a: [number,number,number], b: [number,number,number], t: number): string {
  const r = Math.round(a[0] + (b[0] - a[0]) * t)
  const g = Math.round(a[1] + (b[1] - a[1]) * t)
  const bl = Math.round(a[2] + (b[2] - a[2]) * t)
  return `rgb(${r},${g},${bl})`
}

/** Draw the live dot: expanding ring pulse, white outer circle, colored inner dot. */
export function drawDot(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  palette: LivelinePalette,
  pulse: boolean = true,
  scrubAmount: number = 0,
  now_ms: number = performance.now(),
): void {
  const baseAlpha = ctx.globalAlpha
  const dim = scrubAmount * 0.7

  // Expanding ring pulse (accent colored, every 1.5s) — suppress when dimmed
  if (pulse && dim < 0.3) {
    const t = (now_ms % PULSE_INTERVAL) / PULSE_DURATION
    if (t < 1) {
      const radius = 9 + t * 12
      const pulseAlpha = 0.35 * (1 - t) * (1 - dim * 3)
      ctx.beginPath()
      ctx.arc(x, y, radius, 0, Math.PI * 2)
      ctx.strokeStyle = palette.line
      ctx.lineWidth = 1.5
      ctx.globalAlpha = baseAlpha * pulseAlpha
      ctx.stroke()
    }
  }

  // Outer bg color for blending
  const outerRgb = parseColorRgb(palette.badgeOuterBg)

  // White outer circle with subtle shadow
  ctx.save()
  ctx.globalAlpha = baseAlpha
  ctx.shadowColor = palette.badgeOuterShadow
  ctx.shadowBlur = 6 * (1 - dim)
  ctx.shadowOffsetY = 1
  ctx.beginPath()
  ctx.arc(x, y, 6.5, 0, Math.PI * 2)
  ctx.fillStyle = palette.badgeOuterBg
  ctx.fill()
  ctx.restore()

  // Colored inner dot — blend toward outer bg when dimmed
  ctx.globalAlpha = baseAlpha
  ctx.beginPath()
  ctx.arc(x, y, 3.5, 0, Math.PI * 2)
  if (dim > 0.01) {
    const lineRgb = parseColorRgb(palette.line)
    ctx.fillStyle = lerpColor(lineRgb, outerRgb, dim)
  } else {
    ctx.fillStyle = palette.line
  }
  ctx.fill()
}

/** Draw a multi-series endpoint dot with optional pulse ring (colored ring + solid dot, no white outer, no shadow). */
export function drawMultiDot(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  color: string,
  pulse: boolean = true,
  now_ms: number = performance.now(),
  radius: number = 3,
): void {
  const baseAlpha = ctx.globalAlpha

  // Expanding ring pulse (series-colored, every 1.5s)
  if (pulse) {
    const t = (now_ms % PULSE_INTERVAL) / PULSE_DURATION
    if (t < 1) {
      const ringRadius = 9 + t * 10
      const pulseAlpha = 0.3 * (1 - t)
      ctx.beginPath()
      ctx.arc(x, y, ringRadius, 0, Math.PI * 2)
      ctx.strokeStyle = color
      ctx.lineWidth = 1.5
      ctx.globalAlpha = baseAlpha * pulseAlpha
      ctx.stroke()
    }
  }

  // Solid colored dot (no white outer, no shadow)
  ctx.globalAlpha = baseAlpha
  ctx.beginPath()
  ctx.arc(x, y, radius, 0, Math.PI * 2)
  ctx.fillStyle = color
  ctx.fill()
}

/** Draw a small colored dot for multi-series endpoints (no ring, no pulse, no shadow). */
export function drawSimpleDot(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  color: string,
  radius: number = 3,
): void {
  ctx.beginPath()
  ctx.arc(x, y, radius, 0, Math.PI * 2)
  ctx.fillStyle = color
  ctx.fill()
}

/** Draw momentum arrows (chevrons) next to the dot. */
export function drawArrows(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  momentum: Momentum,
  palette: LivelinePalette,
  arrows: ArrowState,
  dt: number,
  now_ms: number = performance.now(),
): void {
  const baseAlpha = ctx.globalAlpha

  // Update arrow opacities — fade out old direction fully before fading in new
  const upTarget = momentum === 'up' ? 1 : 0
  const downTarget = momentum === 'down' ? 1 : 0

  const canFadeInUp = arrows.down < 0.02
  const canFadeInDown = arrows.up < 0.02

  arrows.up = lerp(arrows.up, canFadeInUp ? upTarget : 0, upTarget > arrows.up ? 0.08 : 0.04, dt)
  arrows.down = lerp(arrows.down, canFadeInDown ? downTarget : 0, downTarget > arrows.down ? 0.08 : 0.04, dt)

  if (arrows.up < 0.01) arrows.up = 0
  if (arrows.down < 0.01) arrows.down = 0
  if (arrows.up > 0.99) arrows.up = 1
  if (arrows.down > 0.99) arrows.down = 1

  // Draw chevrons — directional cascade animation.
  // UP: bottom arrow fires first, then top (energy moves upward).
  // DOWN: top arrow fires first, then bottom.
  const cycle = (now_ms % 1400) / 1400
  const drawChevrons = (dir: -1 | 1, opacity: number) => {
    if (opacity < 0.01) return
    const baseX = x + 19
    const baseY = y

    ctx.save()
    ctx.strokeStyle = palette.gridLabel
    ctx.lineWidth = 2.5
    ctx.lineCap = 'round'
    ctx.lineJoin = 'round'

    for (let i = 0; i < 2; i++) {
      // Stagger: arrow 0 brightens at t=0, arrow 1 at t=0.2
      // Both always visible (min 0.3), cascade just brightens each in sequence
      const start = i * 0.2
      const dur = 0.35
      const localT = cycle - start
      const wave = (localT >= 0 && localT < dur)
        ? Math.sin((localT / dur) * Math.PI)
        : 0
      const pulse = 0.3 + 0.7 * wave

      ctx.globalAlpha = baseAlpha * opacity * pulse

      const nudge = dir === -1 ? -3 : 3
      const cy = baseY + dir * (i * 8 - 4) + nudge
      ctx.beginPath()
      ctx.moveTo(baseX - 5, cy - dir * 3.5)
      ctx.lineTo(baseX, cy)
      ctx.lineTo(baseX + 5, cy - dir * 3.5)
      ctx.stroke()
    }

    ctx.restore()
  }

  drawChevrons(-1, arrows.up)
  drawChevrons(1, arrows.down)

  ctx.globalAlpha = baseAlpha
}

import type { LivelinePalette, ChartLayout } from '../types'

export interface MultiSeriesHoverEntry {
  color: string
  label: string
  value: number
}

export function drawCrosshair(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  hoverX: number,
  hoverValue: number,
  hoverTime: number,
  formatValue: (v: number) => string,
  formatTime: (t: number) => string,
  scrubOpacity: number,
  tooltipY?: number,
  liveDotX?: number,
  tooltipOutline?: boolean,
) {
  if (scrubOpacity < 0.01) return

  const { h, pad, toY } = layout
  const y = toY(hoverValue)

  // Vertical line (solid, like Kalshi)
  ctx.save()
  ctx.globalAlpha = scrubOpacity * 0.5
  ctx.strokeStyle = palette.crosshairLine
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.moveTo(hoverX, pad.top)
  ctx.lineTo(hoverX, h - pad.bottom)
  ctx.stroke()
  ctx.restore()

  // Dot at intersection — solid accent color, always fully opaque.
  // Radius scales with scrubOpacity for smooth appear/disappear.
  const dotRadius = 4 * Math.min(scrubOpacity * 3, 1)
  if (dotRadius > 0.5) {
    ctx.globalAlpha = 1
    ctx.beginPath()
    ctx.arc(hoverX, y, dotRadius, 0, Math.PI * 2)
    ctx.fillStyle = palette.line
    ctx.fill()
  }

  // Top label: "$VALUE - TIME" — fixed at top, moves horizontally only
  // Skip text for small containers (text is ~200px wide)
  if (scrubOpacity < 0.1 || layout.w < 300) return

  const valueText = formatValue(hoverValue)
  const timeText = formatTime(hoverTime)
  const separator = '  ·  '

  ctx.save()
  ctx.globalAlpha = scrubOpacity
  ctx.font = '400 13px "SF Mono", Menlo, monospace'

  const valueW = ctx.measureText(valueText).width
  const sepW = ctx.measureText(separator).width
  const timeW = ctx.measureText(timeText).width
  const totalW = valueW + sepW + timeW

  // Center on crosshair, clamp to chart bounds
  // Right edge of tooltip text aligns with the right edge of the live dot circle
  let tx = hoverX - totalW / 2
  const minX = pad.left + 4
  const dotRightEdge = liveDotX != null ? liveDotX + 7 : layout.w - pad.right
  const maxX = dotRightEdge - totalW
  if (tx < minX) tx = minX
  if (tx > maxX) tx = maxX

  const ty = pad.top + (tooltipY ?? 14) + 10 // offset from top

  ctx.textAlign = 'left'

  // Text outline for readability against the chart
  if (tooltipOutline) {
    ctx.strokeStyle = palette.tooltipBg
    ctx.lineWidth = 3
    ctx.lineJoin = 'round'
    ctx.strokeText(valueText, tx, ty)
    ctx.strokeText(separator + timeText, tx + valueW, ty)
  }

  // Value (dark)
  ctx.fillStyle = palette.tooltipText
  ctx.fillText(valueText, tx, ty)

  // Separator + time (lighter)
  ctx.fillStyle = palette.gridLabel
  ctx.fillText(separator + timeText, tx + valueW, ty)

  ctx.restore()
}

/** Multi-series crosshair: vertical line + inline text at top, matching single-series style. */
export function drawMultiCrosshair(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  hoverX: number,
  hoverTime: number,
  entries: MultiSeriesHoverEntry[],
  formatValue: (v: number) => string,
  formatTime: (t: number) => string,
  scrubOpacity: number,
  tooltipY?: number,
  tooltipOutline?: boolean,
  liveDotX?: number,
) {
  if (scrubOpacity < 0.01 || entries.length === 0) return

  const { h, pad, toY } = layout

  // Vertical line (solid, matching single-series)
  ctx.save()
  ctx.globalAlpha = scrubOpacity * 0.5
  ctx.strokeStyle = palette.crosshairLine
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.moveTo(hoverX, pad.top)
  ctx.lineTo(hoverX, h - pad.bottom)
  ctx.stroke()
  ctx.restore()

  // Dots at each series intersection — radius scales with scrubOpacity,
  // alpha stays at 1 (matching single-series crosshair dot behavior)
  const dotRadius = 4 * Math.min(scrubOpacity * 3, 1)
  if (dotRadius > 0.5) {
    ctx.globalAlpha = 1
    for (const entry of entries) {
      const y = toY(entry.value)
      ctx.beginPath()
      ctx.arc(hoverX, y, dotRadius, 0, Math.PI * 2)
      ctx.fillStyle = entry.color
      ctx.fill()
    }
  }

  if (scrubOpacity < 0.1 || layout.w < 300) return

  // Inline text at top — same style as single-series crosshair
  // Format: "TIME  ·  ● Label Value  ·  ● Label Value"
  ctx.save()
  ctx.globalAlpha = scrubOpacity
  ctx.font = '400 13px "SF Mono", Menlo, monospace'
  ctx.textAlign = 'left'

  const timeText = formatTime(hoverTime)
  const sep = '  ·  '
  const dotInline = ' '  // spacing for inline colored dot

  // Build segments: [ { text, color } ... ]
  type Seg = { text: string; color: string; isDot?: boolean }
  const segments: Seg[] = [
    { text: timeText, color: palette.gridLabel },
  ]
  for (const e of entries) {
    segments.push({ text: sep, color: palette.gridLabel })
    // Inline dot (drawn as circle, not text)
    segments.push({ text: dotInline, color: e.color, isDot: true })
    const label = e.label ? `${e.label} ` : ''
    if (label) segments.push({ text: label, color: palette.gridLabel })
    segments.push({ text: formatValue(e.value), color: palette.tooltipText })
  }

  // Measure total width
  let totalW = 0
  const segWidths: number[] = []
  for (const seg of segments) {
    const w = seg.isDot ? 12 : ctx.measureText(seg.text).width
    segWidths.push(w)
    totalW += w
  }

  // Position — center on crosshair, clamp to chart bounds
  // Right edge of tooltip aligns with the right edge of live dots (matching single-series)
  let tx = hoverX - totalW / 2
  const minX = pad.left + 4
  const dotRightEdge = liveDotX != null ? liveDotX + 7 : layout.w - pad.right
  const maxX = dotRightEdge - totalW
  if (tx < minX) tx = minX
  if (tx > maxX) tx = maxX

  const ty = pad.top + (tooltipY ?? 14) + 10

  // Outline pass
  if (tooltipOutline !== false) {
    ctx.strokeStyle = palette.tooltipBg
    ctx.lineWidth = 3
    ctx.lineJoin = 'round'
    let ox = tx
    for (let i = 0; i < segments.length; i++) {
      const seg = segments[i]
      if (!seg.isDot) {
        ctx.strokeText(seg.text, ox, ty)
      }
      ox += segWidths[i]
    }
  }

  // Fill pass
  let ox = tx
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i]
    if (seg.isDot) {
      // Draw small colored circle inline
      ctx.beginPath()
      ctx.arc(ox + 4, ty - 4, 3.5, 0, Math.PI * 2)
      ctx.fillStyle = seg.color
      ctx.fill()
    } else {
      ctx.fillStyle = seg.color
      ctx.fillText(seg.text, ox, ty)
    }
    ox += segWidths[i]
  }

  ctx.restore()
}

import type { LivelinePalette, ChartLayout } from '../types'
import { niceTimeInterval } from '../math/intervals'
import { lerp } from '../math/lerp'

export interface TimeAxisState {
  labels: Map<number, { alpha: number; text: string }>
}

const FADE = 0.08

export function drawTimeAxis(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  windowSecs: number,
  targetWindowSecs: number,
  formatTime: (t: number) => string,
  state: TimeAxisState,
  dt: number,
) {
  const { h, pad, leftEdge, rightEdge, toX } = layout
  const chartLeft = pad.left
  const chartRight = layout.w - pad.right
  const chartW = chartRight - chartLeft
  const fadeZone = 50

  const edgeAlpha = (x: number): number => {
    const fromLeft = x - chartLeft
    const fromRight = chartRight - x
    const fromEdge = Math.min(fromLeft, fromRight)
    if (fromEdge >= fadeZone) return 1
    if (fromEdge <= 0) return 0
    return fromEdge / fadeZone
  }

  ctx.font = palette.labelFont

  // Interval fully derived from target window — no dependency on the
  // interpolating display. Prevents a one-frame flicker when the transition
  // ends and windowSecs snaps to targetWindowSecs.
  const targetPxPerSec = chartW / targetWindowSecs
  let interval = niceTimeInterval(targetWindowSecs)
  while (interval * targetPxPerSec < 60 && interval < targetWindowSecs) {
    interval *= 2
  }

  // Generate labels: current view + 1 interval buffer.
  // Cap at 30 labels as a safety valve — during wide→narrow transitions the
  // target interval can be tiny relative to the current display span.
  // For day+ intervals, align to local midnight instead of UTC epoch.
  const useLocalDays = interval >= 86400
  let firstTime: number
  if (useLocalDays) {
    const d = new Date((leftEdge - interval) * 1000)
    d.setHours(0, 0, 0, 0)
    firstTime = d.getTime() / 1000
  } else {
    firstTime = Math.ceil((leftEdge - interval) / interval) * interval
  }
  const targets = new Set<number>()
  for (let t = firstTime; t <= rightEdge + interval && targets.size < 30; t += interval) {
    targets.add(Math.round(t * 100))
  }

  // Create or update labels. Text is updated in-place — no crossfade needed
  // because format changes coincide with scroll transitions where the eye
  // tracks movement, not text content. By the time labels settle, the text
  // is already correct so nothing visibly changes on stationary labels.
  for (const key of targets) {
    const text = formatTime(key / 100)
    const existing = state.labels.get(key)
    if (!existing) {
      state.labels.set(key, { alpha: 0, text })
    } else {
      existing.text = text
    }
  }

  // Update alphas
  for (const [key, label] of state.labels) {
    const x = toX(key / 100)
    const isTarget = targets.has(key)
    const target = isTarget ? edgeAlpha(x) : 0
    let next = lerp(label.alpha, target, FADE, dt)
    if (Math.abs(next - target) < 0.02) next = target
    if (next < 0.01 && target === 0) {
      state.labels.delete(key)
    } else {
      label.alpha = next
    }
  }

  // Draw
  const baseAlpha = ctx.globalAlpha
  const lineY = h - pad.bottom
  const tickLen = 5

  ctx.strokeStyle = palette.gridLine
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.moveTo(chartLeft, lineY)
  ctx.lineTo(chartRight, lineY)
  ctx.stroke()

  ctx.textAlign = 'center'

  // Collect, sort by X, resolve overlaps by keeping the more-visible label
  const labels: { x: number; alpha: number; text: string; w: number }[] = []
  for (const [key, label] of state.labels) {
    if (label.alpha < 0.02) continue
    const x = toX(key / 100)
    if (x < chartLeft - 20 || x > chartRight) continue
    const w = ctx.measureText(label.text).width
    labels.push({ x, alpha: label.alpha, text: label.text, w })
  }
  labels.sort((a, b) => a.x - b.x)

  // Resolve overlaps: when two labels collide, keep the higher-alpha one.
  // This gives a clean one-time crossover (no flickering) because one alpha
  // is always rising while the other is falling.
  const drawn: typeof labels = []
  for (const label of labels) {
    const left = label.x - label.w / 2
    if (drawn.length > 0) {
      const prev = drawn[drawn.length - 1]
      const prevRight = prev.x + prev.w / 2
      if (left < prevRight + 8) {
        // Overlap — swap in the higher-alpha label
        if (label.alpha > prev.alpha) {
          drawn[drawn.length - 1] = label
        }
        continue
      }
    }
    drawn.push(label)
  }

  for (const label of drawn) {
    ctx.save()
    ctx.globalAlpha = baseAlpha * label.alpha

    ctx.strokeStyle = palette.gridLine
    ctx.lineWidth = 1
    ctx.beginPath()
    ctx.moveTo(label.x, lineY)
    ctx.lineTo(label.x, lineY + tickLen)
    ctx.stroke()

    ctx.fillStyle = palette.timeLabel
    ctx.fillText(label.text, label.x, lineY + tickLen + 14)

    ctx.restore()
  }
}

import type { LivelinePalette, ChartLayout, OrderbookData } from '../types'

// Green: rgb(34, 197, 94), Red: rgb(239, 68, 68)
const GREEN: [number, number, number] = [34, 197, 94]
const RED: [number, number, number] = [239, 68, 68]

interface StreamLabel {
  y: number
  text: string
  green: boolean
  life: number
  maxLife: number
  intensity: number // 0-1, bigger orders = brighter
}

export interface OrderbookState {
  labels: StreamLabel[]
  spawnTimer: number
  smoothSpeed: number
  // Orderbook churn tracking
  prevBidTotal: number
  prevAskTotal: number
  churnRate: number // smoothed 0-1, how much the book is changing
}

export function createOrderbookState(): OrderbookState {
  return {
    labels: [], spawnTimer: 0, smoothSpeed: BASE_SPEED,
    prevBidTotal: 0, prevAskTotal: 0, churnRate: 0,
  }
}

const MAX_LABELS = 50
const LABEL_LIFETIME = 6 // seconds
const SPAWN_INTERVAL = 40 // ms
const MIN_LABEL_GAP = 22 // px
const BASE_SPEED = 60 // px/s calm
const MAX_SPEED = 160 // px/s during big activity

function mixColor(
  from: [number, number, number],
  to: [number, number, number],
  t: number,
): string {
  const r = Math.round(from[0] + (to[0] - from[0]) * t)
  const g = Math.round(from[1] + (to[1] - from[1]) * t)
  const b = Math.round(from[2] + (to[2] - from[2]) * t)
  return `rgb(${r},${g},${b})`
}

/**
 * Kalshi-style orderbook: left-aligned column spanning full chart height.
 * Labels decelerate as they rise — fast entry at bottom, slow drift at top.
 * Speed driven by two signals:
 *   1. swingMagnitude — price momentum (proxy for activity)
 *   2. orderbook churn — how much the bid/ask data itself is changing
 * Whichever signal is stronger wins. Works with both demo and production data.
 */
export function drawOrderbook(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  orderbook: OrderbookData,
  dt: number,
  state: OrderbookState,
  swingMagnitude: number,
): void {
  const { pad, h, chartH } = layout
  const dtSec = dt / 1000

  if (orderbook.bids.length === 0 && orderbook.asks.length === 0) return

  let maxSize = 0
  let bidTotal = 0
  let askTotal = 0
  for (const [, size] of orderbook.bids) { bidTotal += size; if (size > maxSize) maxSize = size }
  for (const [, size] of orderbook.asks) { askTotal += size; if (size > maxSize) maxSize = size }
  if (maxSize === 0) return

  // Measure orderbook churn: how much total size changed since last frame
  // Normalized by the total size so it's scale-independent
  const totalSize = bidTotal + askTotal
  const prevTotal = state.prevBidTotal + state.prevAskTotal
  let churnSignal = 0
  if (prevTotal > 0) {
    const delta = Math.abs(bidTotal - state.prevBidTotal) + Math.abs(askTotal - state.prevAskTotal)
    churnSignal = Math.min(delta / prevTotal, 1) // 0-1
  }
  state.prevBidTotal = bidTotal
  state.prevAskTotal = askTotal

  // Smooth the churn rate (fast attack, slower decay)
  const churnLerp = churnSignal > state.churnRate ? 0.3 : 0.05
  state.churnRate += (churnSignal - state.churnRate) * churnLerp

  // Activity = max of price momentum and orderbook churn
  const activity = Math.max(Math.min(swingMagnitude * 5, 1), state.churnRate)

  // Drive speed from activity
  const targetSpeed = BASE_SPEED + activity * (MAX_SPEED - BASE_SPEED)
  const speedLerp = 1 - Math.pow(0.95, dt / 16.67)
  state.smoothSpeed += (targetSpeed - state.smoothSpeed) * speedLerp
  const speed = state.smoothSpeed

  const labelX = pad.left + 8
  const bottomY = h - pad.bottom - 6
  const topY = pad.top
  const bg = palette.bgRgb

  // Spawn new labels at bottom
  state.spawnTimer += dt
  while (state.spawnTimer >= SPAWN_INTERVAL && state.labels.length < MAX_LABELS) {
    state.spawnTimer -= SPAWN_INTERVAL

    // Check overlap against ALL existing labels near spawn point
    let tooClose = false
    for (let j = 0; j < state.labels.length; j++) {
      if (Math.abs(state.labels[j].y - bottomY) < MIN_LABEL_GAP) {
        tooClose = true
        break
      }
    }
    if (tooClose) break

    // Weighted random pick
    const allLevels: { size: number; green: boolean }[] = []
    for (const [, size] of orderbook.bids) allLevels.push({ size, green: true })
    for (const [, size] of orderbook.asks) allLevels.push({ size, green: false })

    let totalWeight = 0
    for (const l of allLevels) totalWeight += l.size
    let r = Math.random() * totalWeight
    let picked = allLevels[0]
    for (const l of allLevels) {
      r -= l.size
      if (r <= 0) { picked = l; break }
    }

    const sizeRatio = picked.size / maxSize
    state.labels.push({
      y: bottomY,
      text: `+ ${formatSize(picked.size)}`,
      green: picked.green,
      life: LABEL_LIFETIME,
      maxLife: LABEL_LIFETIME,
      intensity: 0.5 + sizeRatio * 0.5,
    })
  }

  // Update positions — decelerate as labels rise (fast at bottom, slow at top)
  const range = bottomY - topY
  let writeIdx = 0
  for (let i = 0; i < state.labels.length; i++) {
    const l = state.labels[i]
    l.life -= dtSec
    if (l.life <= 0) continue
    const yProgress = range > 0 ? (l.y - topY) / range : 1 // 1 at bottom, 0 at top
    l.y -= speed * (0.7 + 0.3 * yProgress) * dtSec
    if (l.y < topY - 14) continue
    state.labels[writeIdx++] = l
  }
  state.labels.length = writeIdx

  // Draw
  const baseAlpha = ctx.globalAlpha
  ctx.save()
  ctx.font = '600 13px "SF Mono", Menlo, monospace'
  ctx.textAlign = 'left'
  ctx.textBaseline = 'middle'
  ctx.globalAlpha = baseAlpha

  const outlineColor = `rgb(${bg[0]},${bg[1]},${bg[2]})`

  for (let i = 0; i < state.labels.length; i++) {
    const l = state.labels[i]
    const lifeRatio = l.life / l.maxLife

    // Fade in quickly, fade out near top of chart
    const fadeIn = Math.min((1 - lifeRatio) * 10, 1)
    const yRatio = (l.y - topY) / chartH
    const fadeOut = yRatio < 0.45 ? yRatio / 0.45 : 1

    const colorStrength = l.intensity * fadeIn * fadeOut
    const baseColor = l.green ? GREEN : RED
    const fillColor = mixColor(baseColor, bg, 1 - colorStrength)

    ctx.strokeStyle = outlineColor
    ctx.lineWidth = 4
    ctx.lineJoin = 'round'
    ctx.strokeText(l.text, labelX, l.y)

    ctx.fillStyle = fillColor
    ctx.fillText(l.text, labelX, l.y)
  }

  ctx.restore()
}

function formatSize(size: number): string {
  if (size >= 10) return `$${Math.round(size)}`
  if (size >= 1) return `$${size.toFixed(1)}`
  return `$${size.toFixed(2)}`
}

import type { Momentum, DegenOptions } from '../types'

interface Particle {
  x: number
  y: number
  vx: number
  vy: number
  life: number    // 0-1, starts at 1
  size: number
  color: string
}

export interface ParticleState {
  particles: Particle[]
  cooldown: number  // ms remaining before next burst
  burstCount: number // consecutive fires — resets when magnitude drops below threshold
}

export function createParticleState(): ParticleState {
  return { particles: [], cooldown: 0, burstCount: 0 }
}

const MAX_PARTICLES = 80
const PARTICLE_LIFETIME = 1.0 // seconds
const COOLDOWN_MS = 400
const MAGNITUDE_THRESHOLD = 0.08 // fire when swing > 8% of visible range
const MAX_BURSTS = 3 // max consecutive fires before requiring a calm period

/**
 * Spawn particles on large upward swings. Returns the burst intensity
 * (0 = didn't fire, 0-1 = falloff) so the caller can scale shake.
 *
 * Small, fast-moving dots that disperse widely from the live dot position.
 * Accent-colored with alpha fade.
 */
export function spawnOnSwing(
  state: ParticleState,
  momentum: Momentum,
  dotX: number,
  dotY: number,
  swingMagnitude: number,
  accentColor: string,
  dt: number,
  options?: DegenOptions,
): number {
  state.cooldown = Math.max(0, state.cooldown - dt)

  if (momentum === 'flat') return 0
  if (state.cooldown > 0) return 0

  // Below threshold — reset burst counter (calm period)
  if (swingMagnitude < MAGNITUDE_THRESHOLD) {
    state.burstCount = 0
    return 0
  }

  // Down-momentum disabled by default
  if (momentum === 'down' && options?.downMomentum !== true) return 0

  // Burst limiter — max consecutive fires, resets on calm
  if (state.burstCount >= MAX_BURSTS) return 0

  state.cooldown = COOLDOWN_MS

  const scale = options?.scale ?? 1
  const isUp = momentum === 'up'

  // Burst falloff — first burst is biggest, subsequent taper off.
  // Big swings (mag > 0.6) override the falloff so they always feel impactful.
  const mag = Math.min(swingMagnitude * 5, 1)
  const burstFalloff = mag > 0.6 ? 1 : [1, 0.6, 0.35][state.burstCount] ?? 0.35
  state.burstCount++

  const count = Math.round((12 + mag * 20) * scale * burstFalloff)
  const speedMultiplier = 1.0 + mag * 0.8

  for (let i = 0; i < count && state.particles.length < MAX_PARTICLES; i++) {
    // Wide burst — almost a full semicircle for maximum dispersal
    const baseAngle = isUp ? -Math.PI / 2 : Math.PI / 2
    const spread = Math.PI * 1.2
    const angle = baseAngle + (Math.random() - 0.5) * spread
    const speed = (60 + Math.random() * 100) * speedMultiplier

    state.particles.push({
      x: dotX + (Math.random() - 0.5) * 24,
      y: dotY + (Math.random() - 0.5) * 8,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: 1,
      size: (1 + Math.random() * 1.2) * scale * burstFalloff,
      color: accentColor,
    })
  }

  return burstFalloff
}

/**
 * Update and draw particles.
 */
export function drawParticles(
  ctx: CanvasRenderingContext2D,
  state: ParticleState,
  dt: number,
): void {
  if (state.particles.length === 0) return

  const dtSec = dt / 1000

  ctx.save()

  let writeIdx = 0
  for (let i = 0; i < state.particles.length; i++) {
    const p = state.particles[i]
    p.life -= dtSec / PARTICLE_LIFETIME
    if (p.life <= 0) continue

    p.x += p.vx * dtSec
    p.y += p.vy * dtSec
    p.vx *= 0.95  // less drag — particles travel further
    p.vy *= 0.95

    ctx.globalAlpha = p.life * 0.55
    ctx.fillStyle = p.color
    ctx.beginPath()
    ctx.arc(p.x, p.y, p.size * (0.5 + p.life * 0.5), 0, Math.PI * 2)
    ctx.fill()

    state.particles[writeIdx++] = p
  }
  state.particles.length = writeIdx

  ctx.restore()
}

import type { ChartLayout, LivelinePalette, CandlePoint } from '../types'

export type { CandlePoint } from '../types'

const BULL = '#22c55e'
const BEAR = '#ef4444'

// Pre-parsed RGB for fast interpolation
const BULL_RGB = [34, 197, 94] as const
const BEAR_RGB = [239, 68, 68] as const

/** Blend bear→bull by t (0=bear, 1=bull). */
function blendColor(t: number): string {
  const r = Math.round(BEAR_RGB[0] + (BULL_RGB[0] - BEAR_RGB[0]) * t)
  const g = Math.round(BEAR_RGB[1] + (BULL_RGB[1] - BEAR_RGB[1]) * t)
  const b = Math.round(BEAR_RGB[2] + (BULL_RGB[2] - BEAR_RGB[2]) * t)
  return `rgb(${r},${g},${b})`
}

/** Parse "#rrggbb" or "rgb(r,g,b)" to [r,g,b]. */
function parseRgb(color: string): [number, number, number] {
  const hex = color.match(/^#([0-9a-f]{6})$/i)
  if (hex) {
    const h = hex[1]
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)]
  }
  const rgb = color.match(/rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/)
  if (rgb) return [+rgb[1], +rgb[2], +rgb[3]]
  return [128, 128, 128]
}

/** Blend a candle color toward an accent color by t. */
function blendToAccent(candleColor: string, accentColor: string, t: number): string {
  if (t <= 0) return candleColor
  if (t >= 1) return accentColor
  const [r1, g1, b1] = parseRgb(candleColor)
  const [r2, g2, b2] = parseRgb(accentColor)
  const r = Math.round(r1 + (r2 - r1) * t)
  const g = Math.round(g1 + (g2 - g1) * t)
  const b = Math.round(b1 + (b2 - b1) * t)
  return `rgb(${r},${g},${b})`
}

/**
 * Compute pixel dimensions for candle rendering.
 */
function candleDims(layout: ChartLayout, candleWidthSecs: number) {
  const pxPerSec = layout.chartW / (layout.rightEdge - layout.leftEdge)
  const candlePxW = candleWidthSecs * pxPerSec
  const bodyW = Math.max(1, candlePxW * 0.7)
  const wickW = Math.max(0.8, Math.min(2, bodyW * 0.15))
  const radius = bodyW > 6 ? 1.5 : 0
  return { bodyW, wickW, radius }
}

/**
 * Rounded rect helper — draws path only (caller fills/strokes).
 */
function roundedRect(
  ctx: CanvasRenderingContext2D,
  x: number, y: number, w: number, h: number, r: number,
) {
  if (r <= 0 || h < r * 2) {
    ctx.rect(x, y, w, h)
    return
  }
  ctx.moveTo(x + r, y)
  ctx.lineTo(x + w - r, y)
  ctx.arcTo(x + w, y, x + w, y + r, r)
  ctx.lineTo(x + w, y + h - r)
  ctx.arcTo(x + w, y + h, x + w - r, y + h, r)
  ctx.lineTo(x + r, y + h)
  ctx.arcTo(x, y + h, x, y + h - r, r)
  ctx.lineTo(x, y + r)
  ctx.arcTo(x, y, x + r, y, r)
  ctx.closePath()
}

/**
 * Draw OHLC candlesticks with live candle glow + scrub dimming.
 * Respects incoming ctx.globalAlpha for cross-fade/reveal support.
 */
export function drawCandlesticks(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  candles: CandlePoint[],
  candleWidthSecs: number,
  liveTime: number,
  now_ms: number,
  scrubX: number,
  scrubDim: number,
  liveAlpha = 1,
  liveBullBlend = -1,
  accentColor?: string,
  accentBlend = 0,
) {
  if (candles.length === 0) return

  const { toX, toY } = layout
  const { bodyW, wickW, radius } = candleDims(layout, candleWidthSecs)
  const halfBody = bodyW / 2
  const padL = layout.pad.left
  const padR = layout.pad.left + layout.chartW

  // Live pulse: subtle brightness cycle
  const livePulse = 0.12 + Math.sin(now_ms * 0.004) * 0.08

  for (const c of candles) {
    const cx = toX(c.time + candleWidthSecs / 2)
    if (cx + halfBody < padL || cx - halfBody > padR) continue

    const isBull = c.close >= c.open
    const isLive = c.time === liveTime
    let color = isLive && liveBullBlend >= 0 ? blendColor(liveBullBlend) : (isBull ? BULL : BEAR)
    if (accentColor && accentBlend > 0.01) {
      color = blendToAccent(color, accentColor, accentBlend)
    }

    // Scrub dimming: smooth spatial gradient from cursor position
    let candleAlpha = isLive ? liveAlpha : 1
    if (scrubDim > 0.01 && scrubX > 0) {
      const dist = cx - scrubX
      if (dist > 0) {
        const fadeZone = bodyW * 1.5
        const dimT = Math.min(dist / fadeZone, 1)
        candleAlpha *= 1 - scrubDim * 0.5 * dimT
      }
    }

    const baseAlpha = ctx.globalAlpha
    ctx.globalAlpha = baseAlpha * candleAlpha

    // Body geometry
    const bodyTop = toY(Math.max(c.open, c.close))
    const bodyBottom = toY(Math.min(c.open, c.close))
    const bodyH = Math.max(1, bodyBottom - bodyTop)

    // Wicks
    const wickTop = toY(c.high)
    const wickBottom = toY(c.low)
    ctx.lineCap = 'round'
    ctx.strokeStyle = color

    if (bodyTop - wickTop > 0.5) {
      ctx.beginPath()
      ctx.moveTo(cx, bodyTop)
      ctx.lineTo(cx, wickTop)
      ctx.lineWidth = wickW
      ctx.stroke()
    }
    if (wickBottom - bodyBottom > 0.5) {
      ctx.beginPath()
      ctx.moveTo(cx, bodyBottom)
      ctx.lineTo(cx, wickBottom)
      ctx.lineWidth = wickW
      ctx.stroke()
    }

    // Body
    ctx.fillStyle = color
    ctx.beginPath()
    roundedRect(ctx, cx - halfBody, bodyTop, bodyW, bodyH, radius)
    ctx.fill()

    // Live candle glow
    if (isLive) {
      ctx.save()
      ctx.globalAlpha = baseAlpha * candleAlpha * livePulse
      ctx.shadowColor = color
      ctx.shadowBlur = 8
      ctx.fillStyle = color
      ctx.beginPath()
      roundedRect(ctx, cx - halfBody, bodyTop, bodyW, bodyH, radius)
      ctx.fill()
      ctx.restore()
    }

    ctx.globalAlpha = baseAlpha
  }
}

/**
 * Draw a dashed horizontal line at the live close price.
 * Dims when scrubbing, uses candle direction color.
 */
export function drawClosePrice(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  liveCandle: CandlePoint,
  scrubDim: number,
  bullBlend = -1,
) {
  const y = layout.toY(liveCandle.close)
  if (y < layout.pad.top || y > layout.h - layout.pad.bottom) return

  const isBull = liveCandle.close >= liveCandle.open
  const color = bullBlend >= 0 ? blendColor(bullBlend) : (isBull ? BULL : BEAR)

  const baseAlpha = ctx.globalAlpha
  ctx.save()
  ctx.setLineDash([4, 4])
  ctx.strokeStyle = color
  ctx.lineWidth = 1
  ctx.globalAlpha = baseAlpha * (1 - scrubDim * 0.3) * 0.4
  ctx.beginPath()
  ctx.moveTo(layout.pad.left, y)
  ctx.lineTo(layout.w - layout.pad.right, y)
  ctx.stroke()
  ctx.setLineDash([])
  ctx.restore()
}

/**
 * Draw candlestick crosshair: vertical line + OHLC tooltip.
 * All elements respect `opacity` for smooth fade in/out.
 */
export function drawCandleCrosshair(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  hoverX: number,
  candle: CandlePoint,
  hoverTime: number,
  formatValue: (v: number) => string,
  formatTime: (t: number) => string,
  opacity: number,
) {
  if (opacity < 0.01) return

  const { h, pad } = layout

  // Vertical line
  ctx.save()
  ctx.globalAlpha = opacity * 0.5
  ctx.strokeStyle = palette.crosshairLine
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.moveTo(hoverX, pad.top)
  ctx.lineTo(hoverX, h - pad.bottom)
  ctx.stroke()
  ctx.restore()

  // Tooltip — OHLC + time (matches line chart crosshair patterns)
  if (opacity < 0.1 || layout.w < 200) return

  const isBull = candle.close >= candle.open
  const valueColor = isBull ? BULL : BEAR

  const cl = formatValue(candle.close)
  const time = formatTime(hoverTime)

  ctx.save()
  ctx.globalAlpha = opacity
  ctx.font = '400 13px "SF Mono", Menlo, monospace'
  ctx.textAlign = 'left'

  // Full OHLC at ≥400px, condensed (close + time) at smaller sizes
  let parts: { text: string; color: string }[]
  if (layout.w >= 400) {
    const o = formatValue(candle.open)
    const hi = formatValue(candle.high)
    const lo = formatValue(candle.low)
    parts = [
      { text: 'O ', color: palette.gridLabel },
      { text: o, color: valueColor },
      { text: '   H ', color: palette.gridLabel },
      { text: hi, color: valueColor },
      { text: '   L ', color: palette.gridLabel },
      { text: lo, color: valueColor },
      { text: '   C ', color: palette.gridLabel },
      { text: cl, color: valueColor },
      { text: '  \u00b7  ', color: palette.gridLabel },
      { text: time, color: palette.gridLabel },
    ]
  } else {
    parts = [
      { text: 'C ', color: palette.gridLabel },
      { text: cl, color: valueColor },
      { text: '  \u00b7  ', color: palette.gridLabel },
      { text: time, color: palette.gridLabel },
    ]
  }

  // Measure
  let totalW = 0
  const widths: number[] = []
  for (const p of parts) {
    const w = ctx.measureText(p.text).width
    widths.push(w)
    totalW += w
  }

  // Position — center on hover, clamp to chart bounds
  let tx = hoverX - totalW / 2
  const minX = pad.left + 4
  const maxX = layout.w - pad.right - totalW
  if (tx < minX) tx = minX
  if (tx > maxX) tx = maxX
  const ty = pad.top + 24

  // Outline stroke for readability
  ctx.strokeStyle = palette.tooltipBg
  ctx.lineWidth = 3
  ctx.lineJoin = 'round'
  let cx = tx
  for (let i = 0; i < parts.length; i++) {
    ctx.strokeText(parts[i].text, cx, ty)
    cx += widths[i]
  }

  // Fill text
  cx = tx
  for (let i = 0; i < parts.length; i++) {
    ctx.fillStyle = parts[i].color
    ctx.fillText(parts[i].text, cx, ty)
    cx += widths[i]
  }

  ctx.restore()
}

/**
 * Simplified crosshair for line mode — single value + time (no OHLC).
 */
export function drawLineModeCrosshair(
  ctx: CanvasRenderingContext2D,
  layout: ChartLayout,
  palette: LivelinePalette,
  hoverX: number,
  value: number,
  hoverTime: number,
  formatValue: (v: number) => string,
  formatTime: (t: number) => string,
  opacity: number,
) {
  if (opacity < 0.01) return

  const { h, pad } = layout
  const y = layout.toY(value)

  ctx.save()
  ctx.globalAlpha = opacity * 0.5
  ctx.strokeStyle = palette.crosshairLine
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.moveTo(hoverX, pad.top)
  ctx.lineTo(hoverX, h - pad.bottom)
  ctx.stroke()

  ctx.globalAlpha = opacity * 0.3
  ctx.beginPath()
  ctx.moveTo(pad.left, y)
  ctx.lineTo(layout.w - pad.right, y)
  ctx.stroke()
  ctx.restore()

  if (opacity < 0.1 || layout.w < 200) return

  const val = formatValue(value)
  const time = formatTime(hoverTime)

  ctx.save()
  ctx.globalAlpha = opacity
  ctx.font = '400 13px "SF Mono", Menlo, monospace'
  ctx.textAlign = 'left'

  const parts: { text: string; color: string }[] = [
    { text: val, color: palette.line },
    { text: '  \u00b7  ', color: palette.gridLabel },
    { text: time, color: palette.gridLabel },
  ]

  let totalW = 0
  const widths: number[] = []
  for (const p of parts) {
    const w = ctx.measureText(p.text).width
    widths.push(w)
    totalW += w
  }

  let tx = hoverX - totalW / 2
  const minX = pad.left + 4
  const maxX = layout.w - pad.right - totalW
  if (tx < minX) tx = minX
  if (tx > maxX) tx = maxX
  const ty = pad.top + 24

  ctx.strokeStyle = palette.tooltipBg
  ctx.lineWidth = 3
  ctx.lineJoin = 'round'
  let lx = tx
  for (let i = 0; i < parts.length; i++) {
    ctx.strokeText(parts[i].text, lx, ty)
    lx += widths[i]
  }

  lx = tx
  for (let i = 0; i < parts.length; i++) {
    ctx.fillStyle = parts[i].color
    ctx.fillText(parts[i].text, lx, ty)
    lx += widths[i]
  }

  ctx.restore()
}

@import "tailwindcss";
/* shadow-plugin (flornkm) — smooth, layered shadow stacks. The unprefixed
 * entry maps them onto Tailwind's --shadow-xs…2xl scale; our semantic tokens
 * below build on those values so the whole app picks up the smooth shadows. */
@import "shadow-plugin/unprefixed";

@custom-variant dark (&:where(.dark, .dark *));

/* GENERIC FOUNDATION — tokens, @theme, base rules, the primitive-*
 * spacing utilities, and shared keyframes below are needed by EVERY
 * component. Blocks tagged COMPONENT-SPECIFIC further down belong to
 * one primitive each. */
/* ──────────────────────────────────────────────────────────
 * Beautiful UI — design tokens
 * Cool near-white canvas, white cards, hairline borders, layered
 * single-digit-opacity shadows, a neutral ink ramp, and semantic
 * color used sparingly as a condiment.
 * ────────────────────────────────────────────────────────── */

:root {
  /* surfaces — cool, blue-tinted neutrals */
  --page: oklch(0.985 0.001 286.376);
  --canvas: oklch(0.961 0.002 247.84);
  --surface: oklch(1 0 0);
  --inset: oklch(0.979 0.002 247.839);
  --hover: oklch(0.97 0.002 247.839);
  --hover-2: oklch(0.933 0.003 247.86);

  /* ink ramp */
  --ink: oklch(0.247 0.006 258.361);
  --ink-2: oklch(0.506 0.01 264.477);
  --ink-3: oklch(0.695 0.009 264.505);

  /* borders — solid and crisp, not alpha */
  --line: oklch(0.946 0.003 264.542);
  --line-strong: oklch(0.912 0.005 258.326);
  --line-soft: oklch(0.966 0.002 264.542);
  --grid-line: color-mix(in srgb, var(--line) 78%, transparent);
  --field: oklch(0.961 0.001 286.375);
  --stripe: oklch(0.405 0 0 / 0.075);
  --stripe-bg: oklch(0.97 0 0);

  /* accent */
  --accent: oklch(0.626 0.205 254.947);
  --accent-ink: oklch(0.556 0.187 255.617);
  --accent-tint: oklch(0.96 0.019 252.878);

  /* semantic */
  --green: oklch(0.603 0.155 150.883);
  --green-tint: oklch(0.958 0.017 159.118);
  --orange: oklch(0.689 0.179 49.902);
  --orange-tint: oklch(0.964 0.021 67.581);
  --red: oklch(0.621 0.192 23.042);
  --red-tint: oklch(0.956 0.017 17.462);

  /* chart overlays — neutral system colors with enough contrast on either theme */
  --tooltip-bg: oklch(0.272 0.008 264.435);
  --tooltip-fg: oklch(0.976 0.002 247.839);
  --tooltip-muted: oklch(0.731 0.008 260.731);
  --tooltip-border: oklch(0.356 0.007 264.474);

  /* shadows — our solid hairline ring + shadow-plugin's smooth layered stacks
   * (--shadow-xs…lg come from shadow-plugin/unprefixed) so every surface reads
   * consistently across the app. */
  --shadow-hairline: 0 0 0 1px var(--line);
  --shadow-btn: 0 0 0 1px var(--line-strong), var(--shadow-xs);
  --shadow-card: 0 0 0 1px var(--line), var(--shadow-sm);
  --shadow-raised: 0 0 0 1px var(--line), var(--shadow-md);
  --shadow-overlay: 0 0 0 1px var(--line), var(--shadow-lg);
  --shadow-inset-field: inset 0 1px 2px oklch(0 0 0 / 0.12);
}

.dark {
  --page: oklch(0.209 0.004 264.477);
  --canvas: oklch(0.231 0.004 264.487);
  --surface: oklch(0.26 0.006 271.191);
  --inset: oklch(0.243 0.004 264.492);
  --hover: oklch(0.289 0.006 271.22);
  --hover-2: oklch(0.318 0.007 274.747);

  --ink: oklch(0.964 0.002 247.839);
  --ink-2: oklch(0.731 0.008 260.731);
  --ink-3: oklch(0.541 0.01 264.484);

  --line: oklch(0.308 0.006 258.354);
  --line-strong: oklch(0.356 0.007 264.474);
  --line-soft: oklch(0.278 0.006 258.354);
  --field: oklch(0.293 0.006 271.223);
  --stripe: oklch(1 0 0 / 0.055);
  --stripe-bg: oklch(0.226 0.004 264.485);

  --accent: oklch(0.68 0.173 253.301);
  --accent-ink: oklch(0.788 0.113 248.33);
  --accent-tint: oklch(0.68 0.173 253.301 / 0.16);

  --green: oklch(0.705 0.154 153.814);
  --green-tint: oklch(0.705 0.154 153.814 / 0.14);
  --orange: oklch(0.746 0.156 55.642);
  --orange-tint: oklch(0.746 0.156 55.642 / 0.14);
  --red: oklch(0.666 0.18 21.433);
  --red-tint: oklch(0.666 0.18 21.433 / 0.14);

  --tooltip-bg: oklch(0.182 0.004 264.459);
  --tooltip-fg: oklch(0.964 0.002 247.839);
  --tooltip-muted: oklch(0.731 0.008 260.731);
  --tooltip-border: oklch(0.308 0.006 258.354);

  --shadow-hairline: 0 0 0 1px var(--line);
  /* Elevation rings go to a subtle *light* hairline in dark mode: the ring
   * paints over the surface behind the element, so a low-alpha white edge
   * dissolves into the shadow as one continuous stroke (per smooth-shadow-ring),
   * graduated by how far the surface floats. */
  --shadow-btn: 0 0 0 1px oklch(1 0 0 / 0.1), 0 1px 2px oklch(0 0 0 / 0.3);
  --shadow-card:
    0 0 0 1px oklch(1 0 0 / 0.11), 0 1px 2px oklch(0 0 0 / 0.2),
    0 2px 6px oklch(0 0 0 / 0.2);
  --shadow-raised:
    0 0 0 1px oklch(1 0 0 / 0.13), 0 2px 10px oklch(0 0 0 / 0.22);
  --shadow-overlay:
    0 0 0 1px oklch(1 0 0 / 0.15), 0 8px 28px oklch(0 0 0 / 0.34);
  --shadow-inset-field: inset 0 1px 2px oklch(0 0 0 / 0.4);
}

@theme inline {
  /* colors */
  --color-page: var(--page);
  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-inset: var(--inset);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-hover: var(--hover);
  --color-hover-2: var(--hover-2);
  --color-field: var(--field);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-accent-tint: var(--accent-tint);
  --color-green: var(--green);
  --color-green-tint: var(--green-tint);
  --color-orange: var(--orange);
  --color-orange-tint: var(--orange-tint);
  --color-red: var(--red);
  --color-red-tint: var(--red-tint);

  /* shadows */
  --shadow-hairline: var(--shadow-hairline);
  --shadow-btn: var(--shadow-btn);
  --shadow-inset-field: var(--shadow-inset-field);
  --shadow-card: var(--shadow-card);
  --shadow-raised: var(--shadow-raised);
  --shadow-overlay: var(--shadow-overlay);

  /* type */
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-mono-face), ui-monospace, "SF Mono", monospace;

  /* radii — chips 6, controls 8, cards 10, windows 14, pills 999 */
  --radius-chip: 6px;
  --radius-control: 8px;
  --radius-card: 10px;
  --radius-window: 14px;

  /* easing — strong curves; built-ins are too weak */
  --ease-out-strong: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out-strong: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-link: cubic-bezier(0.16, 1, 0.3, 1);
}

/* ── base ─────────────────────────────────────────────── */

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  background-color: var(--stripe-bg);
  background-image: repeating-linear-gradient(
    -45deg,
    transparent 0,
    transparent 7px,
    var(--stripe) 7px,
    var(--stripe) 8px
  );
  /* Pin the stripe pattern to the viewport so it stays put on scroll. */
  background-attachment: fixed;
  color: var(--ink);
  font-feature-settings: "cv11", "ss01";
  font-size: 14px;
  letter-spacing: -0.01em;
  line-height: 1.5;
}

::selection {
  background: var(--accent-tint);
  color: var(--ink);
}

/* ── interface hygiene (interfaces.dev cheat sheet) ────── */

/* headings balance; descriptions avoid orphans (skip long-form — we have none) */
h1,
h2,
h3,
h4 {
  text-wrap: balance;
}

p {
  text-wrap: pretty;
}

/* underlines clear descenders */
a {
  text-underline-position: from-font;
  text-decoration-skip-ink: auto;
}

/* theme switches swap every token at once — freeze transitions so the flip
 * is one clean repaint instead of hundreds of mismatched color fades */
.theme-switching *,
.theme-switching *::before,
.theme-switching *::after {
  transition: none !important;
}

/* touch: :hover sticks after a tap, so neutralize row/header hovers there */
@media (hover: none) {
  .records-row:hover > .records-cell {
    background: transparent;
  }

  .records-row:hover > td.is-colsel {
    background: color-mix(in srgb, var(--accent) 4%, var(--surface));
  }

  .records-header-button:hover {
    background: transparent;
    color: var(--ink-2);
  }
}

/* Chat overflow uses the same neutral tokens as the surrounding interface. */
.chat-thread-scroll {
  color-scheme: light;
  scrollbar-width: thin;
  scrollbar-color: var(--line-strong) transparent;
}
.dark .chat-thread-scroll {
  color-scheme: dark;
}
.chat-thread-scroll::-webkit-scrollbar {
  width: 6px;
}
.chat-thread-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.chat-thread-scroll::-webkit-scrollbar-thumb {
  background: var(--line-strong);
  border-radius: 999px;
}
.chat-thread-scroll::-webkit-scrollbar-thumb:hover {
  background: var(--ink-3);
}

/* Keep the component nav scrollable but hide its scrollbar. */
.component-nav-scroll {
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* legacy Edge */
}
.component-nav-scroll::-webkit-scrollbar {
  display: none; /* WebKit */
}

@media (min-width: 64rem) {
  .component-nav-scroll {
    -webkit-mask-image: linear-gradient(
      to bottom,
      oklch(0 0 0) 0,
      oklch(0 0 0) calc(100% - 6rem),
      transparent 100%
    );
    mask-image: linear-gradient(
      to bottom,
      oklch(0 0 0) 0,
      oklch(0 0 0) calc(100% - 6rem),
      transparent 100%
    );
  }
}

/* Mobile demo gestures should operate controls and visualizations rather than
 * selecting surrounding labels. Text entry and code remain intentionally
 * selectable. */
@media (hover: none) and (pointer: coarse) {
  .primitive-showcase {
    -webkit-user-select: none;
    user-select: none;
    -webkit-touch-callout: none;
  }

  .primitive-showcase :is(input, textarea, [contenteditable="true"], pre, code) {
    -webkit-user-select: text;
    user-select: text;
    -webkit-touch-callout: default;
  }

  .primitive-showcase :is(a, button, [role="button"]) {
    -webkit-tap-highlight-color: transparent;
  }

  .primitive-showcase :is(a, button, [role="button"]):focus-visible {
    outline: none;
  }

  .primitive-showcase :is(img, svg, canvas) {
    -webkit-user-drag: none;
  }

  .insight-chart-stage {
    touch-action: pan-y;
  }
}

/* Tailwind v4 resets buttons to cursor:default — anything
 * clickable must invite the click */
button:not(:disabled),
[role="button"]:not([aria-disabled="true"]),
label:has(input),
a {
  cursor: pointer;
}


:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

input:focus-visible,
textarea:focus-visible,
select:focus-visible,
[contenteditable]:focus-visible {
  outline: none;
}

.animated-underline {
  position: relative;
  display: inline-block;
}

.animated-underline::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 1px;
  content: "";
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 280ms var(--ease-link);
}

a:hover .animated-underline::after,
a:focus-visible .animated-underline::after {
  transform: scaleX(1);
}

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — StreamingText / ContextCards
 * Favicon source avatars.
 * Copy this block only alongside StreamingText / ContextCards; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.source-avatar {
  box-shadow: 0 0 0 1px oklch(0.21 0.034 263.436 / 0.1);
}

.dark .source-avatar {
  box-shadow: 0 0 0 1px oklch(1 0 0 / 0.08);
}

/* ── primitive spacing system ─────────────────────────────
 * Shared optical offsets for small demo cards. Use these
 * instead of hand-tuning 10/12/14px per component.
 */

.primitive-card-pad {
  padding: 12px;
}

.primitive-card-bar {
  padding: 10px 12px;
}

.primitive-card-footer {
  padding: 10px;
}

.primitive-table-cell {
  padding: 10px 12px;
}

.primitive-icon-button {
  display: inline-flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-control);
}

/* ── shared keyframes ─────────────────────────────────── */

@keyframes shimmer-text {
  from {
    background-position: 150% center;
  }
  to {
    background-position: -50% center;
  }
}

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.home-reveal {
  will-change: opacity, transform, filter;
}

/* The sidebar is one persistent 224px tree clipped by a 52px shell.
 * Every rail glyph remains centered at x=26 in both states. */
/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — SidebarNav
 * The 52↔224px collapsible sidebar tree.
 * Copy this block only alongside SidebarNav; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.sidebar-row {
  width: 208px;
  transition-duration: var(--sidebar-copy-duration);
  transition-timing-function: var(--sidebar-easing);
}

.sidebar-copy {
  opacity: 1;
  transform: translateX(0);
  transition:
    opacity var(--sidebar-copy-duration) ease-out,
    transform var(--sidebar-copy-duration) var(--sidebar-easing);
}

.sidebar-logo,
.sidebar-collapse-control,
.sidebar-expand-control {
  transition-duration: var(--sidebar-copy-duration);
  transition-timing-function: ease-out;
}

.sidebar-expand-control {
  pointer-events: none;
  opacity: 0;
}

.sidebar-glide-highlight {
  right: 8px;
  left: 8px;
}

[data-sidebar-collapsed="true"] .sidebar-row {
  width: 36px;
}

[data-sidebar-collapsed="true"] .sidebar-copy {
  pointer-events: none;
  opacity: 0;
  transform: translateX(calc(var(--sidebar-copy-offset) * -1));
}

[data-sidebar-collapsed="true"] .sidebar-workspace-control {
  pointer-events: none;
}

[data-sidebar-collapsed="true"] .sidebar-logo,
[data-sidebar-collapsed="true"] .sidebar-collapse-control {
  pointer-events: none;
  opacity: 0;
}

[data-sidebar-collapsed="true"] .sidebar-expand-control {
  pointer-events: auto;
  opacity: 1;
}

[data-sidebar-collapsed="true"] .sidebar-glide-highlight {
  right: auto;
  width: 36px;
}

@media (prefers-reduced-motion: reduce) {
  .home-reveal {
    opacity: 1 !important;
    transform: none !important;
    filter: none !important;
  }
}

/* ── records table ────────────────────────────────────────
 * The grid is deliberately more architectural than card-like:
 * one quiet surface, precise rules, and color reserved for
 * meaning. The first column remains an anchor while both axes
 * can move independently inside the table viewport.
 */

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — RecordsTable
 * The full CRM grid, spreadsheet gutter, and AI column (~800 lines).
 * Copy this block only alongside RecordsTable; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.records-shell {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface);
  box-shadow: 0 1px 2px oklch(0 0 0 / 0.06);
}

/* fill mode: the shell stretches to fill its container and drops its own
 * border/radius/shadow so it reads as part of the surrounding card rather
 * than a container-in-a-container. The grid body flexes to fill height. */
.records-shell.is-fill {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  height: 100%;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

.records-shell.is-fill .records-scroll {
  max-height: none;
  flex: 1;
}

.records-toolbar {
  display: flex;
  min-height: 52px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--line-strong);
  background: var(--surface);
}

.records-toolbar-left,
.records-toolbar-right,
.records-company-header,
.records-quiet-button,
.records-secondary-button,
.records-primary-button,
.records-select-button,
.records-strength,
.records-link,
.records-add-calculation {
  display: inline-flex;
  align-items: center;
}

.records-toolbar-left,
.records-toolbar-right {
  gap: 4px;
}

.records-toolbar-right {
  flex-shrink: 0;
}

.records-select-button,
.records-quiet-button,
.records-secondary-button,
.records-primary-button {
  height: 32px;
  gap: 7px;
  border-radius: var(--radius-control);
  padding: 0 10px;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 140ms var(--ease-out-strong), color 140ms var(--ease-out-strong), transform 140ms var(--ease-out-strong), box-shadow 140ms var(--ease-out-strong);
}

.records-select-button {
  gap: 8px;
  color: var(--ink);
  border: 1px solid var(--line);
  background: var(--surface);
}

.records-select-button:hover,
.records-quiet-button:hover,
.records-secondary-button:hover {
  background: var(--hover);
  color: var(--ink);
}

.records-quiet-button {
  color: var(--ink-2);
}

.records-quiet-button.is-active {
  background: var(--accent-tint);
  color: var(--accent-ink);
}

.records-secondary-button {
  border: 1px solid var(--tooltip-border);
  color: var(--ink-2);
  box-shadow: none;
}

.records-primary-button {
  margin-left: 3px;
  background: var(--accent);
  color: oklch(1 0 0);
  box-shadow: none;
}

.records-primary-button:hover {
  filter: saturate(0.9) brightness(1.04);
}

.records-quiet-button:active,
.records-secondary-button:active,
.records-primary-button:active,
.records-select-button:active,
.records-add-calculation:active {
  transform: scale(0.96);
}

.records-database-icon {
  display: inline-flex;
  color: var(--green);
}

.records-filter-wrap {
  position: relative;
}

.records-filter-dot {
  width: 5px;
  height: 5px;
  margin-left: -2px;
  border-radius: 99px;
  background: var(--accent);
}

.records-filter-menu {
  position: absolute;
  z-index: 30;
  top: calc(100% + 7px);
  left: 0;
  width: 190px;
  padding: 6px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-card);
  background: var(--surface);
  box-shadow: var(--shadow-overlay);
  animation: pop-in 160ms var(--ease-out-strong) both;
  transform-origin: top left;
}

.records-sort-menu {
  left: -48px;
}

.records-filter-label {
  padding: 5px 8px 6px;
  color: var(--ink-3);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.records-filter-menu button {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 7px;
  border-radius: var(--radius-chip);
  padding: 7px 8px;
  color: var(--ink-2);
  font-size: 12px;
  text-align: left;
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-filter-menu button:hover,
.records-filter-menu button.is-selected {
  background: var(--hover);
  color: var(--ink);
}

.records-menu-check {
  width: 13px;
  color: var(--accent-ink);
  font-size: 12px;
  font-weight: 500;
  text-align: center;
}

.records-scroll {
  max-height: 438px;
  overflow: auto;
  overscroll-behavior: none;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-gutter: stable;
}

.records-scroll:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.records-table {
  width: 100%;
  min-width: 990px;
  border-collapse: separate;
  border-spacing: 0;
  color: var(--ink);
  font-size: 13px;
  font-weight: 500;
  table-layout: fixed;
}

.records-company-col { width: 270px; }
.records-category-col { width: 275px; }
.records-last-col { width: 190px; }
.records-strength-col { width: 210px; }
.records-link-col { width: 175px; }

.records-table th,
.records-table td {
  border-right: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  text-align: left;
  vertical-align: middle;
}

.records-table tr > :last-child {
  border-right: 0;
}

.records-table thead th {
  position: sticky;
  z-index: 5;
  top: 0;
  height: 35px;
  background: var(--surface);
  color: var(--ink-2);
  font-size: 12.5px;
  font-weight: 500;
}

.records-header-cell {
  padding: 0;
}

.records-resize-handle {
  position: absolute;
  z-index: 12;
  top: 0;
  right: -6px;
  width: 12px;
  height: 100%;
  cursor: col-resize;
  touch-action: none;
}

.records-resize-handle::after {
  position: absolute;
  top: 7px;
  bottom: 7px;
  left: 5px;
  width: 2px;
  border-radius: 99px;
  background: var(--accent);
  content: "";
  opacity: 0;
  transform: scaleY(0.65);
  transition: opacity 120ms ease-out, transform 150ms var(--ease-out-strong);
}

.records-resize-handle:hover::after,
.records-resize-handle.is-resizing::after {
  opacity: 1;
  transform: scaleY(1);
}

.records-header-cell.records-sticky-cell {
  z-index: 7;
}

.records-header-button,
.records-company-header {
  width: 100%;
  height: 35px;
  gap: 8px;
  padding: 0 12px;
}

.records-company-header {
  padding-left: 6px;
}

.records-header-button {
  display: flex;
  align-items: center;
  color: var(--ink-2);
  text-align: left;
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-header-button:hover {
  background: var(--hover);
  color: var(--ink);
}

.records-header-icon {
  display: inline-flex;
  flex-shrink: 0;
  color: var(--ink-3);
}

.records-sort {
  display: inline-flex;
  flex-shrink: 0;
  margin-left: auto;
  opacity: 0;
  transition: opacity 120ms ease-out, transform 160ms var(--ease-out-strong);
}

.records-header-button:hover .records-sort,
.records-sort.is-visible {
  opacity: 1;
}

.records-company-header {
  display: flex;
}

.records-company-header > span:not(.records-checkbox-box) {
  white-space: nowrap;
}

.records-add-field {
  display: inline-flex;
  margin-left: auto;
  color: var(--ink-3);
  opacity: 0;
  transition: opacity 120ms ease-out, color 120ms ease-out;
}

.records-company-header:hover .records-add-field,
.records-add-field:focus-visible {
  opacity: 1;
}

.records-add-field:hover {
  color: var(--ink);
}

.records-checkbox {
  position: relative;
  display: inline-flex;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-chip);
}

.records-checkbox input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.records-checkbox-box {
  display: inline-flex;
  width: 18px;
  height: 18px;
  align-items: center;
  justify-content: center;
  border: 1px solid oklch(0.845 0.011 247.953);
  border-radius: 6px;
  color: oklch(0.446 0.018 251.343);
  background: oklch(1 0 0);
  transition: border-color 140ms ease-out, background-color 140ms ease-out, box-shadow 140ms ease-out, transform 140ms var(--ease-out-strong);
}

.records-checkbox:hover .records-checkbox-box {
  border-color: oklch(0.773 0.016 251.194);
  background: oklch(0.966 0.003 228.784);
}

.records-checkbox:active .records-checkbox-box {
  transform: scale(0.96);
}

.records-checkbox input:focus-visible + .records-checkbox-box {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.records-checkbox-box.is-active {
  border-color: var(--accent);
  color: oklch(1 0 0);
  background: var(--accent);
  box-shadow: none;
}

.records-checkbox-dash {
  width: 8px;
  height: 1.5px;
  border-radius: 99px;
  background: oklch(1 0 0);
}

.dark .records-checkbox-box {
  border-color: oklch(0.45 0.017 254.711);
  color: oklch(0.917 0.007 247.901);
  background: oklch(0.346 0.015 252.294);
}

.dark .records-checkbox:hover .records-checkbox-box {
  border-color: oklch(0.521 0.019 254);
  background: oklch(0.391 0.016 251.761);
}

.dark .records-checkbox-box.is-active {
  border-color: var(--accent);
  color: oklch(1 0 0);
  background: var(--accent);
}

.dark .records-checkbox-dash {
  background: oklch(1 0 0);
}

.records-cell {
  height: 35px;
  padding: 0 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.records-sticky-cell {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--surface);
  box-shadow: 5px 0 8px -10px oklch(0 0 0 / 0.4);
}

.records-company-cell {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-left: 6px;
  overflow: visible;
}

.records-row > .records-cell {
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-row:hover > .records-cell {
  background: var(--hover);
}

.records-row.is-selected > .records-cell {
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
}

/* ── spreadsheet gutter ──────────────────────────────────
 * Row numbers at rest; the checkbox takes their place on
 * hover or once the row is selected. */
.records-rownum {
  display: inline-flex;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  align-items: center;
  justify-content: center;
  color: var(--ink-3);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}

.records-row .records-checkbox {
  display: none;
}

.records-row:hover .records-rownum,
.records-row.is-selected .records-rownum {
  display: none;
}

.records-row:hover .records-checkbox,
.records-row.is-selected .records-checkbox {
  display: inline-flex;
}

/* ── selected column — the property being configured ───── */
.records-table th.is-colsel {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  box-shadow: inset 0 2px 0 var(--accent);
}

th.is-colsel .records-header-button,
th.is-colsel .records-company-header,
th.is-colsel .records-header-icon {
  color: var(--accent-ink);
}

.records-table td.is-colsel {
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
}

.records-row:hover > td.is-colsel {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
}

.records-row.is-selected > td.is-colsel {
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
}

/* ── AI column calculating state ─────────────────────────── */
.records-calc {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.records-pulse {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
  background: var(--accent);
  animation: records-pulse 1.1s ease-in-out infinite;
}

@keyframes records-pulse {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.8);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

/* agent-screen — a static decorative cursor sitting on the capture (for show) */
.agent-cursor {
  position: absolute;
  pointer-events: none;
  filter: drop-shadow(0 1px 1.5px rgba(0, 0, 0, 0.35));
}

.records-company-mark {
  display: inline-flex;
  width: 20px;
  height: 20px;
  flex: 0 0 20px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 6px;
  color: var(--ink-2);
  background: var(--field);
  font-size: 10px;
  font-weight: 500;
}

.records-company-name {
  min-width: 0;
  overflow: hidden;
  color: var(--ink);
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-company-name.has-link:hover,
.records-company-name.has-link:focus-visible {
  color: var(--accent-ink);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.records-tags {
  position: relative;
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: 4px;
  overflow: hidden;
}

.records-tags-measure {
  position: absolute;
  top: 0;
  left: 0;
  display: flex;
  width: max-content;
  gap: 4px;
  pointer-events: none;
  visibility: hidden;
}

.records-tags-measure > span {
  display: inline-flex;
}

.records-tag {
  display: inline-flex;
  height: 23px;
  max-width: 115px;
  align-items: center;
  flex-shrink: 0;
  overflow: hidden;
  cursor: pointer;
  border: 1px solid color-mix(in srgb, var(--tag-base) 32%, var(--surface));
  border-radius: 8px;
  padding: 0 7px;
  color: color-mix(in srgb, var(--tag-base) 92%, var(--ink));
  background: color-mix(in srgb, var(--tag-base) 18%, var(--surface));
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-more-tag {
  display: inline-flex;
  height: 23px;
  align-items: center;
  flex-shrink: 0;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  padding: 0 7px;
  color: var(--ink-3);
  background: var(--inset);
  font-size: 11px;
  font-weight: 500;
}

.records-more-tag {
  border-color: var(--line-strong);
  color: var(--ink-3);
  background: var(--inset);
}

.records-muted {
  color: var(--ink-3);
}

.records-strength {
  gap: 8px;
  color: var(--ink-2);
}

.records-strength-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
}

.records-link {
  max-width: 100%;
  gap: 5px;
  overflow: hidden;
  color: var(--accent-ink);
  text-overflow: ellipsis;
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, currentColor 35%, transparent);
  text-underline-offset: 3px;
  transition: color 120ms ease-out, text-decoration-color 120ms ease-out;
}

.records-link-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-link svg {
  flex-shrink: 0;
}

.records-link:hover,
.records-link:focus-visible {
  color: var(--ink);
  text-decoration-color: currentColor;
}

.records-table tfoot td {
  position: sticky;
  z-index: 4;
  bottom: 0;
  height: 35px;
  background: var(--inset);
  color: var(--ink-2);
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
}

.records-table tfoot .records-sticky-cell {
  z-index: 6;
  background: var(--inset);
}

.records-calculation-label {
  color: var(--ink-2);
  font-weight: 500;
}

.records-footer-value {
  display: inline-flex;
  height: 35px;
  align-items: center;
  vertical-align: middle;
}

.records-calculation-number {
  margin-right: 3px;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.records-add-calculation {
  height: 35px;
  gap: 6px;
  color: var(--ink-3);
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
  transition: color 120ms ease-out, transform 140ms var(--ease-out-strong);
}

.records-add-calculation:hover {
  color: var(--ink);
}

.records-average {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--ink-2);
}

.records-calculation-row-secondary td {
  position: sticky;
  bottom: 35px;
  background: color-mix(in srgb, var(--inset) 70%, var(--surface));
}

.records-calculation-row-secondary .records-sticky-cell {
  position: sticky;
  background: color-mix(in srgb, var(--inset) 70%, var(--surface));
}

.records-footer {
  display: flex;
  min-height: 35px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 12px;
  color: var(--ink-3);
  font-size: 11.5px;
}

.records-footer strong {
  color: var(--ink-2);
  font-weight: 500;
}

.records-footer-hint {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  opacity: 0;
  transition: opacity 160ms ease-out;
}

.records-shell:hover .records-footer-hint {
  opacity: 1;
}

.records-scroll-cue {
  display: inline-flex;
  color: var(--ink-3);
}

@media (max-width: 640px) {
  .records-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .records-toolbar-left,
  .records-toolbar-right {
    width: 100%;
  }

  .records-toolbar-right {
    justify-content: flex-end;
  }

  .records-footer-hint {
    display: none;
  }
}

/* ── filter table electric status colors ─────────────────── */

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — FilterTable
 * Electric status-pill colors.
 * Copy this block only alongside FilterTable; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.filter-status-todo,
.filter-status-progress,
.filter-status-done {
  border: 1px solid transparent;
}

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — InsightCards
 * Liveline chart tooltip + cursor.
 * Copy this block only alongside InsightCards; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.insight-chart-stage {
  overflow: hidden;
}

.insight-chart-cursor {
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--ink);
  opacity: 0.26;
  pointer-events: none;
}

.insight-chart-tooltip-anchor {
  position: absolute;
  z-index: 5;
  top: 8px;
  transform: translateX(-50%);
  pointer-events: none;
}

.insight-chart-tooltip {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 5px 9px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  color: var(--tooltip-fg);
  background: var(--tooltip-bg);
  box-shadow: var(--shadow-overlay);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.insight-chart-tooltip-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.insight-chart-tooltip-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
}

/* Status pills share the same base-hue → color-mix derivation as .records-tag,
 * so both components stay consistent across light and dark. */
.filter-status-todo {
  --tag-base: oklch(0.757 0.153 66.401);
}
.filter-status-progress {
  --tag-base: oklch(0.671 0.118 219.351);
}
.filter-status-done {
  --tag-base: oklch(0.652 0.131 162.865);
}

.filter-status-todo,
.filter-status-progress,
.filter-status-done {
  color: color-mix(in srgb, var(--tag-base) 92%, var(--ink));
  background: color-mix(in srgb, var(--tag-base) 20%, var(--surface));
  border-color: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
}

/* Dark mode — a richer, saturated same-hue fill
 * with bright same-hue text and no visible border (light mode keeps the soft
 * tinted pastels above). Applies to both the records grid and status pills. */
.dark .records-tag,
.dark .filter-status-todo,
.dark .filter-status-progress,
.dark .filter-status-done {
  color: color-mix(in srgb, var(--tag-base) 86%, white);
  background: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
  border-color: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes eq-bounce {
  0%,
  100% {
    transform: scaleY(0.35);
  }
  50% {
    transform: scaleY(1);
  }
}

/* ── StreamText primitive ─────────────────────────────────
 * Fast character reveal: the newest few characters carry a
 * soft, masked blur so the leading edge resolves smoothly as
 * text flows in. The caret holds solid while streaming, then
 * blinks once the string settles. */
/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — StreamText
 * The streaming caret + tail.
 * Copy this block only alongside StreamText; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.stream-tail {
  filter: blur(1.6px);
  -webkit-mask-image: linear-gradient(to right, oklch(0 0 0) 20%, oklch(0 0 0 / 0.2));
  mask-image: linear-gradient(to right, oklch(0 0 0) 20%, oklch(0 0 0 / 0.2));
}

.stream-caret {
  display: inline-block;
  width: 2px;
  height: 1.05em;
  margin-left: 1.5px;
  translate: 0 -0.5px;
  border-radius: 1px;
  background: var(--ink);
  vertical-align: text-bottom;
  animation: caret-blink 1s step-end infinite;
}

.stream-caret.is-streaming {
  animation: none;
}

@keyframes caret-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .stream-caret {
    animation: none;
  }
  .stream-tail {
    filter: none;
    -webkit-mask-image: none;
    mask-image: none;
  }
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* pixel-grid loader — brighten plateau, staggered per cell */
@keyframes pixel-on {
  0%, 100% {
    opacity: 0.15;
  }
  18%, 42% {
    opacity: 1;
  }
  62% {
    opacity: 0.15;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* The upstream tokens are local copies; no parent repository is needed. */
:root { --font-inter: 'Inter Variable'; --font-mono-face: 'JetBrains Mono Variable'; }
body { margin: 0; color: var(--ink); font-family: var(--font-inter), system-ui, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif; }
a, button, summary { -webkit-tap-highlight-color: transparent; }
a.router-link-exact-active { color: var(--ink); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }

html[lang="zh-CN"] { letter-spacing: 0; }
html[lang="zh-CN"] body { letter-spacing: 0; }
